     1→/**
     2→ * Pure-function relevance scorer with no VS Code dependencies.
     3→ * Used for both the VS Code extension (via the wrapper in tabRelevanceScorer.ts)
     4→ * and offline evaluation benchmarks.
     5→ */
     6→
     7→/** Minimal tab representation without VS Code types. */
     8→export interface TabInfoPlain {
     9→  relativePath: string;
    10→  languageId: string;
    11→  fsPath: string;
    12→  estimatedTokens: number;
    13→  relevanceScore: number;
    14→  relevanceReason: string;
    15→  isActive: boolean;
    16→  isDirty: boolean;
    17→  isPinned: boolean;
    18→  diagnosticCount: number;
    19→  lastEditTimestamp: number;
    20→  label: string;
    21→}
    22→
    23→/** Active file context needed for scoring. */
    24→export interface ActiveFileContext {
    25→  text: string;
    26→  languageId: string;
    27→  fsPath: string;
    28→}
    29→
    30→/** Scoring weights (configurable for sensitivity analysis). */
    31→export interface ScoringWeights {
    32→  language: number;
    33→  imports: number;
    34→  path: number;
    35→  recency: number;
    36→  diagnostics: number;
    37→}
    38→
    39→export const DEFAULT_WEIGHTS: ScoringWeights = {
    40→  language: 0.25,
    41→  imports: 0.30,
    42→  path: 0.20,
    43→  recency: 0.15,
    44→  diagnostics: 0.10,
    45→};
    46→
    47→/**
    48→ * Score all tabs relative to the active file using five signals.
    49→ * Returns a new array with updated relevanceScore and relevanceReason.
    50→ */
    51→export function scoreAllPure(
    52→  tabs: TabInfoPlain[],
    53→  activeFile: ActiveFileContext | null,
    54→  weights: ScoringWeights = DEFAULT_WEIGHTS,
    55→  now: number = Date.now(),
    56→): TabInfoPlain[] {
    57→  if (!activeFile) {
    58→    return tabs.map(t => ({ ...t, relevanceScore: 0.5, relevanceReason: 'No active editor' }));
    59→  }
    60→
    61→  const activeImports = extractImports(activeFile.text);
    62→  const activePath = activeFile.fsPath;
    63→  const activeLang = activeFile.languageId;
    64→
    65→  return tabs.map(tab => {
    66→    let score = 0;
    67→    const reasons: string[] = [];
    68→
    69→    // 1. Same language
    70→    if (tab.languageId === activeLang) {
    71→      score += weights.language;
    72→      reasons.push('same language');
    73→    }
    74→
    75→    // 2. Import relationship
    76→    if (matchesImport(tab.relativePath, activeImports)) {
    77→      score += weights.imports;
    78→      reasons.push('imported by active file');
    79→    }
    80→
    81→    // 3. Path similarity
    82→    const pathScore = computePathSimilarity(activePath, tab.fsPath);
    83→    score += pathScore * weights.path;
    84→    if (pathScore > 0.5) {
    85→      reasons.push('nearby path');
    86→    }
    87→
    88→    // 4. Recency of edit
    89→    const ageMs = now - tab.lastEditTimestamp;
    90→    const ageMinutes = ageMs / 60000;
    91→    if (ageMinutes < 2) {
    92→      score += weights.recency;
    93→      reasons.push('recently edited');
    94→    } else if (ageMinutes < 10) {
    95→      score += 0.08;
    96→      reasons.push('edited recently');
    97→    }
    98→
    99→    // 5. Diagnostics
   100→    if (tab.diagnosticCount > 0) {
   101→      score += weights.diagnostics;
   102→      reasons.push(`${tab.diagnosticCount} diagnostics`);
   103→    }
   104→
   105→    // 6. Pinned — always maximum relevance
   106→    if (tab.isPinned) {
   107→      score = 1.0;
   108→      reasons.length = 0;
   109→      reasons.push('📌 pinned');
   110→    }
   111→
   112→    // 7. Active file — always maximum
   113→    if (tab.isActive) {
   114→      score = 1.0;
   115→      reasons.length = 0;
   116→      reasons.push('active editor');
   117→    }
   118→
   119→    return {
   120→      ...tab,
   121→      relevanceScore: Math.min(score, 1.0),
   122→      relevanceReason: reasons.join(', ') || 'low relevance',
   123→    };
   124→  });
   125→}
   126→
   127→/**
   128→ * Extract import paths from source text (TS/JS, Python, Go, Java).
   129→ */
   130→export function extractImports(text: string): string[] {
   131→  const imports: string[] = [];
   132→
   133→  // TypeScript / JavaScript
   134→  const tsImports = text.matchAll(/(?:import\s+.*?from\s+['"](.+?)['"]|require\s*\(\s*['"](.+?)['"]\s*\))/g);
   135→  for (const match of tsImports) {
   136→    imports.push(match[1] || match[2]);
   137→  }
   138→
   139→  // Python
   140→  const pyImports = text.matchAll(/(?:from\s+([\w.]+)\s+import|import\s+([\w.]+))/g);
   141→  for (const match of pyImports) {
   142→    imports.push((match[1] || match[2]).replace(/\./g, '/'));
   143→  }
   144→
   145→  // Go
   146→  const goImports = text.matchAll(/import\s+(?:\w+\s+)?"(.+?)"/g);
   147→  for (const match of goImports) {
   148→    imports.push(match[1]);
   149→  }
   150→
   151→  // Java
   152→  const javaImports = text.matchAll(/import\s+([\w.]+);/g);
   153→  for (const match of javaImports) {
   154→    imports.push(match[1].replace(/\./g, '/'));
   155→  }
   156→
   157→  return imports;
   158→}
   159→
   160→/**
   161→ * Check if a tab's path matches any import from the active file.
   162→ */
   163→export function matchesImport(relativePath: string, imports: string[]): boolean {
   164→  const tabName = fileNameNoExt(relativePath);
   165→  const tabPath = relativePath.replace(/\\/g, '/');
   166→
   167→  for (const imp of imports) {
   168→    const normalizedImport = imp.replace(/\\/g, '/').replace(/^\.\//, '');
   169→
   170→    // Direct match: import ends with tab's filename
   171→    if (normalizedImport.endsWith(tabName)) {
   172→      const beforeName = normalizedImport.slice(0, -tabName.length);
   173→      if (beforeName === '' || beforeName.endsWith('/')) {
   174→        return true;
   175→      }
   176→    }
   177→
   178→    // Path suffix match
   179→    const importWithoutExt = normalizedImport.replace(/\.[^/.]+$/, '');
   180→    const tabWithoutExt = tabPath.replace(/\.[^/.]+$/, '');
   181→    if (tabWithoutExt.endsWith(importWithoutExt)) {
   182→      const beforeMatch = tabWithoutExt.slice(0, -importWithoutExt.length);
   183→      if (beforeMatch === '' || beforeMatch.endsWith('/')) {
   184→        return true;
   185→      }
   186→    }
   187→  }
   188→
   189→  return false;
   190→}
   191→
   192→/**
   193→ * Compute path similarity based on shared directory prefix segments.
   194→ */
   195→export function computePathSimilarity(pathA: string, pathB: string): number {
   196→  const normA = pathA.replace(/\\/g, '/');
   197→  const normB = pathB.replace(/\\/g, '/');
   198→  const dirA = normA.split('/').slice(0, -1);
   199→  const dirB = normB.split('/').slice(0, -1);
   200→
   201→  if (dirA.length === 0 || dirB.length === 0) { return 0; }
   202→
   203→  let shared = 0;
   204→  for (let i = 0; i < Math.min(dirA.length, dirB.length); i++) {
   205→    if (dirA[i] === dirB[i]) { shared++; } else { break; }
   206→  }
   207→
   208→  if (shared === dirA.length && shared === dirB.length) {
   209→    return 1.0;
   210→  }
   211→
   212→  const maxDepth = Math.max(dirA.length, dirB.length);
   213→  return shared / maxDepth;
   214→}
   215→
   216→function fileNameNoExt(filePath: string): string {
   217→  const base = filePath.split('/').pop() || '';
   218→  return base.replace(/\.[^.]+$/, '');
   219→}
