     1→import * as vscode from 'vscode';
     2→import { TabInfo, BudgetBreakdown } from './types';
     3→import { TokenizerService } from './tokenizerService';
     4→
     5→/**
     6→ * Estimates token counts for files and tracks total context budget usage.
     7→ *
     8→ * Uses model-specific tokenizers via TokenizerService:
     9→ *  - Anthropic: Claude BPE tokenizer (real token counts)
    10→ *  - OpenAI: o200k_base tokenizer (real token counts)
    11→ *  - Google/other: heuristic (~1 token per 4 chars)
    12→ */
    13→export class TokenBudgetEstimator {
    14→
    15→  // Cached token counts by URI string
    16→  private cache = new Map<string, { tokens: number; version: number; provider: string }>();
    17→
    18→  constructor(private readonly tokenizer: TokenizerService) {}
    19→
    20→  /**
    21→   * Set which provider's tokenizer to use for counting.
    22→   */
    23→  private provider: string = 'anthropic';
    24→
    25→  setProvider(provider: string): void {
    26→    // If provider changed, invalidate cache (different tokenizer = different counts)
    27→    if (provider !== this.provider) {
    28→      this.cache.clear();
    29→      this.provider = provider;
    30→    }
    31→  }
    32→
    33→  /**
    34→   * Estimate tokens for a single document using the real tokenizer.
    35→   */
    36→  async estimateFileTokens(doc: vscode.TextDocument): Promise<number> {
    37→    const key = doc.uri.toString();
    38→    const cached = this.cache.get(key);
    39→
    40→    // Use cache if document version and provider haven't changed
    41→    if (cached && cached.version === doc.version && cached.provider === this.provider) {
    42→      return cached.tokens;
    43→    }
    44→
    45→    const tokens = this.tokenizer.countTokens(doc.getText(), this.provider);
    46→
    47→    this.cache.set(key, { tokens, version: doc.version, provider: this.provider });
    48→    return tokens;
    49→  }
    50→
    51→  /**
    52→   * Estimate tokens for all tabs.
    53→   */
    54→  async estimateAllTabs(tabs: TabInfo[]): Promise<TabInfo[]> {
    55→    const results: TabInfo[] = [];
    56→
    57→    for (const tab of tabs) {
    58→      try {
    59→        // Use already-open documents to avoid force-opening tabs
    60→        const openDoc = vscode.workspace.textDocuments.find(
    61→          d => d.uri.toString() === tab.uri.toString()
    62→        );
    63→        if (openDoc) {
    64→          const tokens = await this.estimateFileTokens(openDoc);
    65→          results.push({ ...tab, estimatedTokens: tokens });
    66→        } else {
    67→          // For tabs without a loaded document, estimate from cache or use 0
    68→          const cached = this.cache.get(tab.uri.toString());
    69→          results.push({ ...tab, estimatedTokens: cached?.tokens ?? 0 });
    70→        }
    71→      } catch {
    72→        results.push({ ...tab, estimatedTokens: 0 });
    73→      }
    74→    }
    75→
    76→    return results;
    77→  }
    78→
    79→  /**
    80→   * Estimate overhead tokens for non-file context (system prompt, instructions, conversation).
    81→   */
    82→  estimateOverhead(chatTurnCount: number, instructionFiles: number): number {
    83→    const systemPrompt = 2000;              // ~2K tokens for Copilot system prompt
    84→    const instructionsCost = instructionFiles * 500;  // ~500 tokens per instruction file
    85→    const conversationCost = chatTurnCount * 800;     // ~800 tokens per turn (user+assistant)
    86→    const outputReservation = 4000;          // tokens reserved for response
    87→
    88→    return systemPrompt + instructionsCost + conversationCost + outputReservation;
    89→  }
    90→
    91→  /**
    92→   * Compute total budget usage.
    93→   */
    94→  computeBudget(
    95→    tabs: TabInfo[],
    96→    chatTurnCount: number,
    97→    instructionFiles: number,
    98→    windowCapacity: number
    99→  ): { used: number; capacity: number; percent: number; breakdown: BudgetBreakdown } {
   100→    const fileTokens = tabs.reduce((sum, t) => sum + t.estimatedTokens, 0);
   101→    const overhead = this.estimateOverhead(chatTurnCount, instructionFiles);
   102→    const used = fileTokens + overhead;
   103→
   104→    return {
   105→      used,
   106→      capacity: windowCapacity,
   107→      percent: Math.min((used / windowCapacity) * 100, 100),
   108→      breakdown: {
   109→        files: fileTokens,
   110→        systemPrompt: 2000,
   111→        instructions: instructionFiles * 500,
   112→        conversation: chatTurnCount * 800,
   113→        outputReservation: 4000,
   114→      },
   115→    };
   116→  }
   117→
   118→  /**
   119→   * Clear the entire cache.
   120→   */
   121→  clearCache(): void {
   122→    this.cache.clear();
   123→  }
   124→
   125→  /**
   126→   * Clear cache for a specific URI (when document closes).
   127→   */
   128→  clearCacheFor(uri: string): void {
   129→    this.cache.delete(uri);
   130→  }
   131→}
   132→
   133→// BudgetBreakdown is defined in types.ts
   134→

