    16→ *  /breakdown    — Show where tokens are going
    17→ *  /instructions — List and estimate tokens for instruction files
    18→ *  /model        — Show or switch the active AI model
    19→ *  /compaction   — Per-turn token growth and compaction recommendations
    20→ *  /reset        — Reset session state (turn counter)
    21→ */
    22→export class ContextChatParticipant implements vscode.Disposable {
    23→
    24→  private participant: vscode.ChatParticipant;
    25→
    26→  constructor(private readonly monitor: ContextMonitor) {
    27→    this.participant = vscode.chat.createChatParticipant(
    28→      'tokalator.tokens',
    29→      this.handleRequest.bind(this),
    30→    );
    31→
    32→    this.participant.iconPath = new vscode.ThemeIcon('symbol-numeric');
    33→  }
    34→
    35→  private async handleRequest(
    36→    request: vscode.ChatRequest,
    37→    context: vscode.ChatContext,
    38→    stream: vscode.ChatResponseStream,
    39→    _token: vscode.CancellationToken,
    40→  ): Promise<vscode.ChatResult> {
    41→
    42→    // Auto-sync Tokalator's model to match the active Copilot model
    43→    await this.syncModelFromRequest(request);
    44→
    45→    // Only count turns for commands that modify state (optimize, pin, unpin)
    46→    // Read-only commands (count, breakdown) don't contribute to context rot
    47→    const isModifyingCommand = request.command === 'optimize' || request.command === 'pin' || request.command === 'unpin';
    48→    if (isModifyingCommand) {
    49→      await this.monitor.incrementChatTurns();
    50→    }
    51→
    52→    switch (request.command) {
    53→      case 'count':
    54→        return this.handleCount(stream);
    55→
    56→      case 'optimize':
    57→        return this.handleOptimize(stream);
    58→
    59→      case 'pin':
    60→        return this.handlePin(request, stream);
    61→
    62→      case 'unpin':
    63→        return this.handleUnpin(request, stream);
    64→
    65→      case 'breakdown':
    66→        return this.handleBreakdown(stream);
    67→
    68→      case 'instructions':
    69→        return this.handleInstructions(stream);
    70→
    71→      case 'model':
    72→        return this.handleModel(request, stream);
    73→
    74→      case 'reset':
    75→        return this.handleReset(stream);
    76→
    77→      case 'compaction':
    78→        return this.handleCompaction(stream);
    79→
    80→      case 'preview':
    81→        return this.handlePreview(request, stream);
    82→
    83→      case 'exit':
    84→        return this.handleExit(stream);
    85→
    86→      default:
    87→        return this.handleDefault(request, stream);
    88→    }
    89→  }
    90→
    91→  /**
    92→   * /count — Token count and budget level
    93→   */
    94→  private async handleCount(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    95→    await this.monitor.refresh();
    96→    const snapshot = this.monitor.getLatestSnapshot();
    97→
    98→    if (!snapshot) {
    99→      stream.markdown('Unable to get token count.');
   100→      return {};
   101→    }
   102→
   103→    const levelEmoji = snapshot.budgetLevel === 'low' ? '🟢'
   104→      : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';
   105→
   106→    stream.markdown(`## ${levelEmoji} Token Budget: ${snapshot.budgetLevel.toUpperCase()}\n\n`);
   107→
   108→    // Simple summary
   109→    stream.markdown(`| | |\n|---|---|\n`);
   110→    stream.markdown(`| **Tabs open** | ${snapshot.tabs.length} |\n`);
   111→    stream.markdown(`| **Tokens used** | ~${this.fmtTokens(snapshot.totalEstimatedTokens)} |\n`);
   112→    stream.markdown(`| **Window size** | ${this.fmtTokens(snapshot.windowCapacity)} |\n`);
   113→    stream.markdown(`| **Tokenizer** | ${snapshot.tokenizerLabel} |\n`);
   114→    stream.markdown(`| **Chat turns** | ${snapshot.chatTurnCount} |\n\n`);
   115→
   116→    // Health notes
   117→    for (const reason of snapshot.healthReasons) {
   118→      stream.markdown(`- ${reason}\n`);
   119→    }
   120→
   121→    // Quick actions
   122→    const config = vscode.workspace.getConfiguration('tokalator');
   123→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   124→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   125→
   126→    if (distractors.length > 0) {
   127→      stream.markdown(`\n> **${distractors.length} low-relevance tabs** — run \`@tokalator /optimize\` to close them\n`);
   128→    }
   129→
   130→    return {};
   131→  }
