   431→
   432→    stream.markdown(`## Token Breakdown\n\n`);
   433→
   434→    // Simple bar
   435→    const barLen = 20;
   436→    const filled = Math.round((snapshot.usagePercent / 100) * barLen);
   437→    const bar = '█'.repeat(filled) + '░'.repeat(barLen - filled);
   438→    stream.markdown(`\`${bar}\` ${snapshot.budgetLevel}\n\n`);
   439→
   440→    // Top files by token usage
   441→    const sorted = [...snapshot.tabs].sort((a, b) => b.estimatedTokens - a.estimatedTokens);
   442→
   443→    stream.markdown(`### Largest files\n\n`);
   444→    stream.markdown(`| File | Tokens | Relevance |\n|---|---|---|\n`);
   445→
   446→    for (const tab of sorted.slice(0, 8)) {
