   448→      stream.markdown(`| ${tab.label} | ~${this.fmtTokens(tab.estimatedTokens)} | ${relIcon} |\n`);
   449→    }
   450→
   451→    // Overhead
   452→    const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
   453→    const overhead = snapshot.totalEstimatedTokens - fileTokens;
   454→    stream.markdown(`| *System overhead* | ~${this.fmtTokens(overhead)} | — |\n\n`);
   455→
   456→    // Distractors
   457→    const config = vscode.workspace.getConfiguration('tokalator');
   458→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   459→    const distractors = sorted.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   460→
   461→    if (distractors.length > 0) {
   462→      const distractorTokens = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
   463→      stream.markdown(`> **${distractors.length} low-relevance files** using ~${this.fmtTokens(distractorTokens)} tokens\n`);
   464→    }
   465→
   466→    return {};
   467→  }
