   503→  /**
   504→   * /instructions — List instruction files and their token cost
   505→   */
   506→  private async handleInstructions(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   507→    stream.progress('Scanning instruction files...');
   508→
   509→    // Find all instruction-like files
   510→    const patterns = [
   511→      '**/*.instructions.md',
   512→      '**/.github/copilot-instructions.md',
   513→      '**/.copilot/*.md',
   514→      '**/*.prompt.md',
   515→      '**/.cursorrules',
   516→      '**/.claude/**/*.md',
   517→      '**/CLAUDE.md',
   518→      '**/AGENTS.md',
   519→      '**/*.agent.md',
   520→    ];
   521→
   522→    const allFiles: { path: string; tokens: number }[] = [];
   523→
   524→    for (const pattern of patterns) {
   525→      try {
   526→        const files = await vscode.workspace.findFiles(pattern, '**/node_modules/**', 50);
   527→        for (const uri of files) {
   528→          try {
   529→            const doc = await vscode.workspace.openTextDocument(uri);
   530→            const model = this.monitor.getActiveModel();
   531→            const tokenizer = this.monitor.getTokenizer();
   532→            const tokens = tokenizer.countTokens(doc.getText(), model.provider);
   533→            allFiles.push({
   534→              path: vscode.workspace.asRelativePath(uri),
   535→              tokens,
   536→            });
   537→          } catch {
   538→            allFiles.push({ path: vscode.workspace.asRelativePath(uri), tokens: 0 });
   539→          }
   540→        }
   541→      } catch {
   542→        // pattern not found
   543→      }
   544→    }
   545→
   546→    if (allFiles.length === 0) {
   547→      stream.markdown('No instruction files found in this workspace.\n\n');
   548→      stream.markdown('Instruction files are automatically attached to AI context. Common patterns:\n\n');
   549→      stream.markdown('| File | Used by |\n|---|---|\n');
   550→      stream.markdown('| `.github/copilot-instructions.md` | GitHub Copilot |\n');
   551→      stream.markdown('| `*.instructions.md` | GitHub Copilot |\n');
   552→      stream.markdown('| `*.prompt.md` | Copilot / Claude |\n');
   553→      stream.markdown('| `AGENTS.md` | Claude Code |\n');
   554→      stream.markdown('| `.cursorrules` | Cursor |\n');
   555→      return {};
   556→    }
   557→
   558→    // Sort by tokens descending
   559→    allFiles.sort((a, b) => b.tokens - a.tokens);
   560→    const totalTokens = allFiles.reduce((sum, f) => sum + f.tokens, 0);
   561→
   562→    stream.markdown(`## Instruction Files\n\n`);
   563→    stream.markdown(`**${allFiles.length} files** using ~${this.fmtTokens(totalTokens)} tokens\n\n`);
   564→    stream.markdown(`| File | Tokens |\n|---|---|\n`);
   565→
   566→    for (const f of allFiles) {
   567→      stream.markdown(`| \`${f.path}\` | ~${this.fmtTokens(f.tokens)} |\n`);
   568→    }
