   123→  private postSnapshot(snapshot: ContextSnapshot): void {
   124→    if (!this.view) { return; }
   125→
   126→    const serialized = {
   127→      ...snapshot,
   128→      pinnedFiles: Array.from(snapshot.pinnedFiles),
   129→      tabs: snapshot.tabs.map(t => ({
   130→        ...t,
   131→        uri: t.uri.toString(),
   132→      })),
   133→      activeFile: snapshot.activeFile
   134→        ? { ...snapshot.activeFile, uri: snapshot.activeFile.uri.toString() }
   135→        : null,
   136→      models: this.monitor.getModels().map(m => ({ id: m.id, label: m.label, provider: m.provider, contextWindow: m.contextWindow })),
   137→      tokenizerType: snapshot.tokenizerType,
   138→      tokenizerLabel: snapshot.tokenizerLabel,
   139→      turnHistory: snapshot.turnHistory,
   140→      budgetBreakdown: snapshot.budgetBreakdown,
   141→    };
   142→
   143→    const lastSession = this.monitor.getLastSession();
   144→    this.view.webview.postMessage({ type: 'snapshot', data: serialized, lastSession });
   145→  }
