import * as vscode from 'vscode';
import { TabInfo, ContextSnapshot, TurnSnapshot, SessionSummary } from './types';
import { TabRelevanceScorer } from './tabRelevanceScorer';
import { TokenBudgetEstimator } from './tokenBudgetEstimator';
import { TokenizerService } from './tokenizerService';
import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel } from './modelProfiles';
import { SessionLogger } from './sessionLogger';

const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
const SESSION_KEY = 'tokalator.lastSession';

/**
 * Core engine that tracks all editor state and produces real-time ContextSnapshots.
 *
 * Subscribes to:
 *  - Active editor changes
 *  - Tab open/close events
 *  - Text document changes
 *  - Diagnostics changes
 *
 * Emits:
 *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
 */
export class ContextMonitor implements vscode.Disposable {

  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;

  private readonly scorer = new TabRelevanceScorer();
  private readonly tokenizer = new TokenizerService();
  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);

  private pinnedFiles = new Set<string>();
  private chatTurnCount = 0;
  private turnHistory: TurnSnapshot[] = [];
  private lastEditTimestamps = new Map<string, number>();
  private disposables: vscode.Disposable[] = [];
  private refreshTimer: ReturnType<typeof setInterval> | undefined;

  private latestSnapshot: ContextSnapshot | null = null;
  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
  private isRefreshing = false;
  private pendingRefresh = false;

  private activeModel: ModelProfile;
  private workspaceFileTokens = 0;
  private workspaceFileCount = 0;

  // Session tracking
  private peakTokens = 0;
  private peakPercent = 0;
  private fileEditCounts = new Map<string, number>();

  // Opt-in session logger for research studies
  private sessionLogger: SessionLogger | null = null;

  constructor(private readonly workspaceState?: vscode.Memento) {
    // Load persisted pinned files (normalize URIs for consistent matching)
    if (workspaceState) {
      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
    }

    // Load persisted model selection
    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
    this.activeModel = getModel(savedModelId);
    this.estimator.setProvider(this.activeModel.provider);

    // Scan workspace files on startup
    this.scanWorkspaceFiles();

    // Debounced refresh to avoid perf issues from rapid event firing
    const debouncedRefresh = () => {
      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
      this.debounceTimer = setTimeout(() => this.refresh(), 300);
    };

    // Subscribe to VS Code events
    this.disposables.push(
      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
      vscode.workspace.onDidChangeTextDocument(e => {
        const uri = e.document.uri.toString();
        this.lastEditTimestamps.set(uri, Date.now());
        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
        debouncedRefresh();
      }),
      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
      // Clean up caches when documents close (memory leak fix)
      vscode.workspace.onDidCloseTextDocument(doc => {
        const uri = doc.uri.toString();
        this.lastEditTimestamps.delete(uri);
        this.estimator.clearCacheFor(uri);
        debouncedRefresh();
      }),
      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
      // Sync model when settings change (skip if already on that model to avoid loop)
      vscode.workspace.onDidChangeConfiguration(e => {
        if (e.affectsConfiguration('tokalator.model')) {
          const cfg = vscode.workspace.getConfiguration('tokalator');
          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
          if (modelId !== this.activeModel.id) {
            this.setModel(modelId);
          }
        }
      }),
    );

    // Periodic refresh for time-based scoring (recency decay)
    const config = vscode.workspace.getConfiguration('tokalator');
    const interval = config.get<number>('autoRefreshInterval', 2000);
    this.refreshTimer = setInterval(() => this.refresh(), interval);

    // Opt-in session logging for research studies
    if (config.get<boolean>('enableSessionLogging', false)) {
      this.sessionLogger = new SessionLogger();
      this.sessionLogger.startSession(this.activeModel.id);
    }

    // Initial snapshot
    this.refresh();
  }

  /**
   * Build a fresh snapshot and emit it.
   */
  async refresh(): Promise<void> {
    if (this.isRefreshing) {
      // Queue one pending refresh so the final state after rapid switching is captured
      this.pendingRefresh = true;
      return;
    }
    this.isRefreshing = true;
    this.pendingRefresh = false;
    try {
      const snapshot = await this.buildSnapshot();
      this.latestSnapshot = snapshot;
      this._onDidUpdateSnapshot.fire(snapshot);

      // Log snapshot to session logger if enabled
      if (this.sessionLogger) {
        this.sessionLogger.logSnapshot(snapshot);
      }
    } finally {
      this.isRefreshing = false;
      // If events arrived while we were refreshing, run one more pass
      if (this.pendingRefresh) {
        this.pendingRefresh = false;
        void this.refresh();
      }
    }
  }

  /**
   * Get the most recent snapshot without triggering a refresh.
   */
  getLatestSnapshot(): ContextSnapshot | null {
    return this.latestSnapshot;
  }

  /**
   * Normalize a URI string for consistent Set matching.
   */
  private normalizeUri(uri: string): string {
    try {
      return vscode.Uri.parse(uri).toString();
    } catch {
      return uri;
    }
  }

  /**
   * Pin a file URI so it's always scored as maximum relevance.
   */
  pinFile(uri: string): void {
    this.pinnedFiles.add(this.normalizeUri(uri));
    this.persistPins();
    this.refresh();
  }

  /**
   * Unpin a file.
   */
  unpinFile(uri: string): void {
    this.pinnedFiles.delete(this.normalizeUri(uri));
    this.persistPins();
    this.refresh();
  }

  /**
   * Clear all pins.
   */
  clearPins(): void {
    this.pinnedFiles.clear();
    this.persistPins();
    this.refresh();
  }

  /**
   * Persist pinned files to workspace state.
   */
  private persistPins(): void {
    if (this.workspaceState) {
      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
    }
  }

  /**
   * Increment the conversation turn counter and capture a turn snapshot.
   * Only call this for actual user interactions, not status checks.
   */
  async incrementChatTurns(): Promise<void> {
    this.chatTurnCount++;

    // Capture a turn snapshot for compaction tracking
    const snapshot = this.latestSnapshot;
    if (snapshot) {
      const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
      const overheadTokens = snapshot.totalEstimatedTokens - fileTokens;
      this.turnHistory.push({
        turn: this.chatTurnCount,
        timestamp: Date.now(),
        inputTokens: snapshot.totalEstimatedTokens,
        outputReserved: this.activeModel.maxOutput,
        fileTokens,
        overheadTokens,
        tabCount: snapshot.tabs.length,
        pinnedCount: this.pinnedFiles.size,
      });
    }

    this.refresh();
  }

  /**
   * Estimate the token cost of the *next* chat turn before sending.
   * This gives users a preview of what will be consumed.
   */
  async previewNextTurn(): Promise<{
    currentInput: number;
    nextTurnEstimate: number;
    conversationGrowth: number;
    outputReserved: number;
    remainingCapacity: number;
    percentAfterTurn: number;
    windowCapacity: number;
    warning: string | null;
  }> {
    await this.refresh();
    const snapshot = this.latestSnapshot;
    if (!snapshot) {
      return {
        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
      };
    }

    // Each turn adds ~800 tokens (user message + assistant response)
    const perTurnCost = 800;
    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);

    let warning: string | null = null;
    if (nextPercent >= 90) {
      warning = 'Next turn will push you past 90% — high risk of context overflow';
    } else if (nextPercent >= 75) {
      warning = 'Approaching context limit — consider closing tabs or resetting';
    }

    // Check if next turn crosses the rot threshold
    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
    }

    return {
      currentInput: snapshot.totalEstimatedTokens,
      nextTurnEstimate: nextTurnInput,
      conversationGrowth: perTurnCost,
      outputReserved: this.activeModel.maxOutput,
      remainingCapacity: remaining,
      percentAfterTurn: nextPercent,
      windowCapacity: snapshot.windowCapacity,
      warning,
    };
  }

  /**
   * Reset conversation turn counter and clear turn history.
   */
  resetChatTurns(): void {
    this.chatTurnCount = 0;
    this.turnHistory = [];
    this.refresh();
  }

  /**
   * Get current chat turn count.
   */
  getChatTurnCount(): number {
    return this.chatTurnCount;
  }

  /**
   * Get the per-turn snapshot history for compaction analysis.
   */
  getTurnHistory(): TurnSnapshot[] {
    return [...this.turnHistory];
  }

  /**
   * Close tabs below relevance threshold.
   * Returns the list of closed tab labels.
   */
  async optimizeTabs(): Promise<string[]> {
    const config = vscode.workspace.getConfiguration('tokalator');
    const threshold = config.get<number>('relevanceThreshold', 0.3);

    const snapshot = await this.buildSnapshot();
    const toClose = snapshot.tabs.filter(
      t => t.relevanceScore < threshold && !t.isActive && !t.isPinned
    );

    const closed: string[] = [];
    for (const tab of toClose) {
      const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
      const vsTab = allTabs.find(t => {
        if (t.input instanceof vscode.TabInputText) {
          return t.input.uri.toString() === tab.uri.toString();
        }
        return false;
      });
      if (vsTab) {
        await vscode.window.tabGroups.close(vsTab);
        closed.push(tab.label);
      }
    }

    // Log optimize action to session logger if enabled
    if (this.sessionLogger && closed.length > 0) {
      this.sessionLogger.logOptimize(closed.length, threshold);
    }

    return closed;
  }

  /**
   * Build the full context snapshot.
   */
  private async buildSnapshot(): Promise<ContextSnapshot> {
    const config = vscode.workspace.getConfiguration('tokalator');
    // Use windowSize setting as override only when it differs from the default (1,000,000)
    const configWindowSize = config.get<number>('windowSize', 1000000);
    const windowCapacity = configWindowSize !== 1000000 ? configWindowSize : this.activeModel.contextWindow;
    const rotWarning = this.activeModel.rotThreshold;

    // 1. Gather all open tabs
    let tabs = this.gatherTabs();

    // 2. Estimate tokens for each tab
    tabs = await this.estimator.estimateAllTabs(tabs);

    // 3. Score relevance
    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);

    // 4. Sort by relevance (highest first)
    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);

    // 5. Gather diagnostics summary
    const diagnosticsSummary = this.gatherDiagnosticsSummary();

    // 6. Count instruction files in workspace
    const instructionFiles = await this.countInstructionFiles();

    // 7. Compute budget
    const budget = this.estimator.computeBudget(
      tabs,
      this.chatTurnCount,
      instructionFiles,
      windowCapacity
    );

    // Track peak usage for session summary
    if (budget.used > this.peakTokens) {
      this.peakTokens = budget.used;
      this.peakPercent = budget.percent;
    }

    // 8. Determine budget level (simplified from percentage)
    let budgetLevel: 'low' | 'medium' | 'high';
    if (budget.percent > 85) {
      budgetLevel = 'high';
    } else if (budget.percent > 60) {
      budgetLevel = 'medium';
    } else {
      budgetLevel = 'low';
    }

    // 9. Determine health and reasons
    const healthReasons: string[] = [];
    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';

    if (budgetLevel === 'high') {
      contextHealth = 'critical';
      healthReasons.push('Token budget is high — context overflow risk');
    } else if (budgetLevel === 'medium') {
      contextHealth = 'warning';
      healthReasons.push('Token budget is medium — consider closing unused tabs');
    }

    if (this.chatTurnCount >= rotWarning) {
      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
    }

    const distractors = tabs.filter(t => {
      const threshold = config.get<number>('relevanceThreshold', 0.3);
      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
    });
    if (distractors.length > 3) {
      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
      healthReasons.push(`${distractors.length} low-relevance tabs open`);
    }

    if (healthReasons.length === 0) {
      healthReasons.push('Token budget looks good');
    }

    const activeFile = tabs.find(t => t.isActive) || null;

    return {
      timestamp: Date.now(),
      activeFile,
      tabs,
      pinnedFiles: this.pinnedFiles,
      totalEstimatedTokens: budget.used,
      windowCapacity,
      usagePercent: budget.percent,
      budgetLevel,
      diagnosticsSummary,
      chatTurnCount: this.chatTurnCount,
      contextHealth,
      healthReasons,
      modelId: this.activeModel.id,
      modelLabel: this.activeModel.label,
      workspaceFileCount: this.workspaceFileCount,
      workspaceFileTokens: this.workspaceFileTokens,
      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
      turnHistory: [...this.turnHistory],
      budgetBreakdown: budget.breakdown,
    };
  }

  /**
   * Gather TabInfo from all open tab groups.
   */
  private gatherTabs(): TabInfo[] {
    const tabs: TabInfo[] = [];
    const seenUris = new Set<string>();
    const workspaceFolders = vscode.workspace.workspaceFolders || [];

    for (const group of vscode.window.tabGroups.all) {
      for (const tab of group.tabs) {
        if (!(tab.input instanceof vscode.TabInputText)) { continue; }

        const uri = tab.input.uri;
        const uriKey = uri.toString();

        // Skip duplicate URIs (same file open in split panes)
        if (seenUris.has(uriKey)) { continue; }
        seenUris.add(uriKey);

        const fsPath = uri.fsPath;

        // Find the matching workspace folder for correct relative path in multi-root workspaces
        const matchingFolder = workspaceFolders.find(f => fsPath.startsWith(f.uri.fsPath));
        const relativePath = matchingFolder
          ? fsPath.replace(matchingFolder.uri.fsPath, '').replace(/^[/\\]/, '')
          : fsPath;

        // Get language ID from open documents
        const openDoc = vscode.workspace.textDocuments.find(
          d => d.uri.toString() === uri.toString()
        );
        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);

        // Get diagnostics for this file
        const diagnostics = vscode.languages.getDiagnostics(uri);
        const diagnosticCount = diagnostics.length;

        // Get last edit timestamp
        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;

        tabs.push({
          uri,
          label: tab.label,
          languageId,
          relativePath,
          estimatedTokens: 0,   // filled later by estimator
          relevanceScore: 0,     // filled later by scorer
          relevanceReason: '',
          isActive: tab.isActive,
          isDirty: tab.isDirty,
          isPinned: this.pinnedFiles.has(uri.toString()),
          diagnosticCount,
          lastEditTimestamp: lastEdit,
        });
      }
    }

    return tabs;
  }

  /**
   * Aggregate diagnostics across all open files.
   */
  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
    const allDiags = vscode.languages.getDiagnostics();
    let errors = 0, warnings = 0, info = 0;

    for (const [, diags] of allDiags) {
      for (const d of diags) {
        switch (d.severity) {
          case vscode.DiagnosticSeverity.Error: errors++; break;
          case vscode.DiagnosticSeverity.Warning: warnings++; break;
          default: info++; break;
        }
      }
    }

    return { errors, warnings, info };
  }

  /**
   * Count .instructions.md files in the workspace (they consume context budget).
   */
  private async countInstructionFiles(): Promise<number> {
    try {
      const exclude = '**/node_modules/**';
      const [instrFiles, copilotInstr, claudeMd, agentsMd, cursorRules] = await Promise.all([
        vscode.workspace.findFiles('**/*.instructions.md', exclude, 20),
        vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1),
        vscode.workspace.findFiles('**/CLAUDE.md', exclude, 5),
        vscode.workspace.findFiles('**/AGENTS.md', exclude, 5),
        vscode.workspace.findFiles('**/.cursorrules', exclude, 5),
      ]);
      return instrFiles.length + copilotInstr.length + claudeMd.length + agentsMd.length + cursorRules.length;
    } catch {
      return 0;
    }
  }

  /**
   * Guess language from file extension.
   */
  private guessLanguage(fsPath: string): string {
    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
    const map: Record<string, string> = {
      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
    };
    return map[ext] || ext;
  }

  /**
   * Set the active model and persist it.
   */
  async setModel(modelId: string): Promise<void> {
    this.activeModel = getModel(modelId);
    this.estimator.setProvider(this.activeModel.provider);
    if (this.workspaceState) {
      this.workspaceState.update(SELECTED_MODEL_KEY, modelId);
    }
    // Sync the VS Code setting so Settings UI / dashboard selector stay in sync
    const cfg = vscode.workspace.getConfiguration('tokalator');
    const currentSetting = cfg.get<string>('model');
    if (currentSetting !== modelId) {
      await cfg.update('model', modelId, vscode.ConfigurationTarget.Global);
    }
    // Rescan workspace with new tokenizer ratios, then refresh dashboard
    await this.scanWorkspaceFiles();
    await this.refresh();
  }

  /**
   * Get the current active model.
   */
  getActiveModel(): ModelProfile {
    return this.activeModel;
  }

  /**
   * Get all available models.
   */
  getModels(): ModelProfile[] {
    return MODEL_PROFILES;
  }

  /**
   * Get the tokenizer service for direct token counting.
   */
  getTokenizer(): TokenizerService {
    return this.tokenizer;
  }

  /**
   * Scan workspace files to estimate total project token count.
   * This runs once on startup and on workspace change.
   */
  private async scanWorkspaceFiles(): Promise<void> {
    try {
      const files = await vscode.workspace.findFiles(
        '**/*.{ts,tsx,js,jsx,py,go,rs,java,rb,md,json,yml,yaml,css,html,sh,sql,c,cpp,h,cs,swift,kt}',
        '{**/node_modules/**,**/dist/**,**/build/**,**/.next/**,**/vendor/**,**/.git/**}',
        5000
      );
      this.workspaceFileCount = files.length;

      // Estimate total workspace tokens using provider-specific byte ratios
      let totalBytes = 0;
      for (const uri of files) {
        try {
          const stat = await vscode.workspace.fs.stat(uri);
          totalBytes += stat.size;
        } catch {
          // skip unreadable files
        }
      }
      this.workspaceFileTokens = this.tokenizer.estimateFromBytes(totalBytes, this.activeModel.provider);
    } catch {
      this.workspaceFileCount = 0;
      this.workspaceFileTokens = 0;
    }
  }

  /**
   * Save a session summary to workspace state for next activation.
   */
  saveSessionSummary(): void {
    const snapshot = this.latestSnapshot;
    if (!snapshot || !this.workspaceState) return;

    const topFiles = [...this.fileEditCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([uri]) => {
        try {
          return vscode.workspace.asRelativePath(vscode.Uri.parse(uri));
        } catch {
          return uri;
        }
      });

    const summary: SessionSummary = {
      endedAt: new Date().toISOString(),
      modelId: this.activeModel.id,
      modelLabel: this.activeModel.label,
      totalTurns: this.chatTurnCount,
      peakTokens: this.peakTokens,
      peakPercent: this.peakPercent,
      tabCount: snapshot.tabs.length,
      pinnedCount: this.pinnedFiles.size,
      filesWorkedOn: topFiles,
      budgetLevel: snapshot.budgetLevel,
      healthStatus: snapshot.contextHealth,
    };

    this.workspaceState.update(SESSION_KEY, summary);
  }

  /**
   * Get last session summary (if any).
   */
  getLastSession(): SessionSummary | undefined {
    return this.workspaceState?.get<SessionSummary>(SESSION_KEY);
  }

  dispose(): void {
    this.saveSessionSummary();
    if (this.sessionLogger) { this.sessionLogger.endSession(); }
    if (this.refreshTimer) { clearInterval(this.refreshTimer); }
    if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
    this._onDidUpdateSnapshot.dispose();
    this.tokenizer.dispose();
    this.disposables.forEach(d => d.dispose());
  }
}

import * as vscode from 'vscode';
import * as path from 'path';
import * as os from 'os';
import { ContextMonitor } from '../core/contextMonitor';
import type { ContextSnapshot } from '../core/types';
import { findModel } from '../core/modelProfiles';

/**
 * Chat participant `@tokalator` for Tokalator.
 *
 * Commands:
 *  /count        — Show current token count and budget level
 *  /optimize     — Close low-relevance tabs
 *  /pin          — Pin a file as always-relevant
 *  /unpin        — Unpin a file
 *  /breakdown    — Show where tokens are going
 *  /instructions — List and estimate tokens for instruction files
 *  /model        — Show or switch the active AI model
 *  /compaction   — Per-turn token growth and compaction recommendations
 *  /reset        — Reset session state (turn counter)
 */
export class ContextChatParticipant implements vscode.Disposable {

  private participant: vscode.ChatParticipant;

  constructor(private readonly monitor: ContextMonitor) {
    this.participant = vscode.chat.createChatParticipant(
      'tokalator.tokens',
      this.handleRequest.bind(this),
    );

    this.participant.iconPath = new vscode.ThemeIcon('symbol-numeric');
  }

  private async handleRequest(
    request: vscode.ChatRequest,
    context: vscode.ChatContext,
    stream: vscode.ChatResponseStream,
    _token: vscode.CancellationToken,
  ): Promise<vscode.ChatResult> {

    // Auto-sync Tokalator's model to match the active Copilot model
    await this.syncModelFromRequest(request);

    // Only count turns for commands that modify state (optimize, pin, unpin)
    // Read-only commands (count, breakdown) don't contribute to context rot
    const isModifyingCommand = request.command === 'optimize' || request.command === 'pin' || request.command === 'unpin';
    if (isModifyingCommand) {
      await this.monitor.incrementChatTurns();
    }

    switch (request.command) {
      case 'count':
        return this.handleCount(stream);

      case 'optimize':
        return this.handleOptimize(stream);

      case 'pin':
        return this.handlePin(request, stream);

      case 'unpin':
        return this.handleUnpin(request, stream);

      case 'breakdown':
        return this.handleBreakdown(stream);

      case 'instructions':
        return this.handleInstructions(stream);

      case 'model':
        return this.handleModel(request, stream);

      case 'reset':
        return this.handleReset(stream);

      case 'compaction':
        return this.handleCompaction(stream);

      case 'preview':
        return this.handlePreview(request, stream);

      case 'exit':
        return this.handleExit(stream);

      default:
        return this.handleDefault(request, stream);
    }
  }

  /**
   * /count — Token count and budget level
   */
  private async handleCount(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    await this.monitor.refresh();
    const snapshot = this.monitor.getLatestSnapshot();

    if (!snapshot) {
      stream.markdown('Unable to get token count.');
      return {};
    }

    const levelEmoji = snapshot.budgetLevel === 'low' ? '🟢'
      : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';

    stream.markdown(`## ${levelEmoji} Token Budget: ${snapshot.budgetLevel.toUpperCase()}\n\n`);

    // Simple summary
    stream.markdown(`| | |\n|---|---|\n`);
    stream.markdown(`| **Tabs open** | ${snapshot.tabs.length} |\n`);
    stream.markdown(`| **Tokens used** | ~${this.fmtTokens(snapshot.totalEstimatedTokens)} |\n`);
    stream.markdown(`| **Window size** | ${this.fmtTokens(snapshot.windowCapacity)} |\n`);
    stream.markdown(`| **Tokenizer** | ${snapshot.tokenizerLabel} |\n`);
    stream.markdown(`| **Chat turns** | ${snapshot.chatTurnCount} |\n\n`);

    // Health notes
    for (const reason of snapshot.healthReasons) {
      stream.markdown(`- ${reason}\n`);
    }

    // Quick actions
    const config = vscode.workspace.getConfiguration('tokalator');
    const threshold = config.get<number>('relevanceThreshold', 0.3);
    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);

    if (distractors.length > 0) {
      stream.markdown(`\n> **${distractors.length} low-relevance tabs** — run \`@tokalator /optimize\` to close them\n`);
    }

    return {};
  }

  /**
   * /optimize — Close low-relevance tabs
   */
  private async handleOptimize(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    stream.progress('Finding low-relevance tabs...');

    const closed = await this.monitor.optimizeTabs();

    if (closed.length === 0) {
      stream.markdown('All tabs look relevant. Nothing to close.\n');
    } else {
      stream.markdown(`## Closed ${closed.length} tabs\n\n`);
      for (const name of closed) {
        stream.markdown(`- ~~${name}~~\n`);
      }
      stream.markdown(`\nYour token budget is now more focused.\n`);
    }

    return {};
  }

  /**
   * /pin — Pin a file
   */
  private async handlePin(
    request: vscode.ChatRequest,
    stream: vscode.ChatResponseStream,
  ): Promise<vscode.ChatResult> {
    const promptValue = this.stripQuotes(request.prompt.trim());
    let targets: vscode.Uri[] = [];

    if (!promptValue) {
      const activeUri = vscode.window.activeTextEditor?.document.uri;
      if (!activeUri) {
        stream.markdown('Specify a file to pin or focus the file you want to pin. Example: `@tokalator /pin src/auth.ts`\n');
        return {};
      }
      targets = [activeUri];
    } else {
      targets = await this.resolveUrisFromInput(promptValue);
      if (targets.length === 0) {
        stream.markdown(`No file found matching \`${promptValue}\`\n`);
        return {};
      }
    }

    const uniqueTargets = this.dedupeUris(targets);
    const pinnedLabels = new Set<string>();

    for (const uri of uniqueTargets) {
      this.monitor.pinFile(uri.toString());
      pinnedLabels.add(vscode.workspace.asRelativePath(uri, false));
    }

    const header = pinnedLabels.size === 1 ? 'Pinned file:' : 'Pinned files:';
    const list = Array.from(pinnedLabels)
      .map(label => `- \`${label}\``)
      .join('\n');

    stream.markdown(`${header}\n${list}\n\nPinned files stay at max relevance and won't be closed by optimize.\n`);
    return {};
  }

  /**
   * /unpin — Unpin a file
   */
  private async handleUnpin(
    request: vscode.ChatRequest,
    stream: vscode.ChatResponseStream,
  ): Promise<vscode.ChatResult> {
    const promptValue = this.stripQuotes(request.prompt.trim());
    let targets: vscode.Uri[] = [];

    if (!promptValue) {
      const activeUri = vscode.window.activeTextEditor?.document.uri;
      if (!activeUri) {
        stream.markdown('Specify a file to unpin or focus the file you want to unpin. Example: `@tokalator /unpin src/auth.ts`\n');
        return {};
      }
      targets = [activeUri];
    } else {
      targets = await this.resolveUrisFromInput(promptValue);
      if (targets.length === 0) {
        stream.markdown(`No file found matching \`${promptValue}\`\n`);
        return {};
      }
    }

    const uniqueTargets = this.dedupeUris(targets);
    const unpinnedLabels: string[] = [];

    for (const uri of uniqueTargets) {
      this.monitor.unpinFile(uri.toString());
      unpinnedLabels.push(vscode.workspace.asRelativePath(uri, false));
    }

    const header = unpinnedLabels.length === 1 ? 'Unpinned file:' : 'Unpinned files:';
    const list = unpinnedLabels
      .map(label => `- \`${label}\``)
      .join('\n');

    stream.markdown(`${header}\n${list}\n\nThese files will now be scored by normal relevance rules.\n`);
    return {};
  }

  /**
   * /reset — Reset session state (turn counter and optionally pins)
   */
  private async handleReset(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    const turnsBefore = this.monitor.getChatTurnCount();
    this.monitor.resetChatTurns();

    stream.markdown(`## Session Reset\n\n`);
    stream.markdown(`- Chat turns: ${turnsBefore} → 0\n`);
    stream.markdown(`- Context rot tracking cleared\n\n`);
    stream.markdown(`> To also clear pinned files, run \`@tokalator /unpin\` or use the **Clear All Pinned Files** command.\n`);
    return {};
  }

  /**
   * /preview — Preview token cost of the next message before sending
   */
  private async handlePreview(
    request: vscode.ChatRequest,
    stream: vscode.ChatResponseStream,
  ): Promise<vscode.ChatResult> {
    const preview = await this.monitor.previewNextTurn();
    const model = this.monitor.getActiveModel();

    stream.markdown(`## 🔮 Next Turn Preview\n\n`);

    // Current state
    const barLen = 20;
    const currentFilled = Math.round(((preview.currentInput / preview.windowCapacity) * 100 / 100) * barLen);
    const nextFilled = Math.round((preview.percentAfterTurn / 100) * barLen);
    const currentBar = '█'.repeat(currentFilled) + '░'.repeat(barLen - currentFilled);
    const nextBar = '█'.repeat(nextFilled) + '░'.repeat(barLen - nextFilled);

    stream.markdown(`| | Tokens | Window |\n|---|---|---|\n`);
    stream.markdown(`| **Now** | ~${this.fmtTokens(preview.currentInput)} | \`${currentBar}\` |\n`);
    stream.markdown(`| **After next turn** | ~${this.fmtTokens(preview.nextTurnEstimate)} | \`${nextBar}\` |\n`);
    stream.markdown(`| **Growth** | +~${this.fmtTokens(preview.conversationGrowth)} | |\n`);
    stream.markdown(`| **Output reserve** | ~${this.fmtTokens(preview.outputReserved)} | |\n`);
    stream.markdown(`| **Remaining** | ~${this.fmtTokens(preview.remainingCapacity)} | |\n\n`);

    // If user typed extra text, count those tokens too
    const userText = request.prompt.trim();
    if (userText) {
      const tokenizer = this.monitor.getTokenizer();
      const textTokens = tokenizer.countTokens(userText, model.provider);
      stream.markdown(`Your message "**${userText.slice(0, 50)}${userText.length > 50 ? '...' : ''}**" ≈ ${this.fmtTokens(textTokens)} tokens\n\n`);
    }

    if (preview.warning) {
      stream.markdown(`> ⚠️ **${preview.warning}**\n\n`);
    } else {
      stream.markdown(`> ✅ You have room for ~**${Math.floor(preview.remainingCapacity / 800)}** more turns at current rate\n\n`);
    }

    stream.markdown(`*Model: ${model.label} · Window: ${this.fmtTokens(model.contextWindow)}*\n`);
    return {};
  }

  /**
   * /exit — End session, save summary, clear state
   */
  private async handleExit(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    this.monitor.saveSessionSummary();

    const turns = this.monitor.getChatTurnCount();
    this.monitor.resetChatTurns();
    this.monitor.clearPins();

    stream.markdown(`## Session Ended\n\n`);
    stream.markdown(`- ${turns} turns completed\n`);
    stream.markdown(`- All pins cleared\n`);
    stream.markdown(`- Session summary saved\n\n`);
    stream.markdown(`> Start a new session anytime with \`@tokalator /count\`\n`);
    return {};
  }

  /**
   * /compaction — Per-turn token growth and compaction recommendations
   */
  private async handleCompaction(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    await this.monitor.refresh();
    const snapshot = this.monitor.getLatestSnapshot();

    if (!snapshot) {
      stream.markdown('Unable to get compaction data.');
      return {};
    }

    const model = this.monitor.getActiveModel();
    const history = snapshot.turnHistory;
    const breakdown = snapshot.budgetBreakdown;

    stream.markdown(`## Context Growth\n\n`);

    // Current budget breakdown
    stream.markdown(`### Budget Breakdown\n\n`);
    stream.markdown(`| Category | Tokens | % of Window |\n|---|---|---|\n`);
    const entries: [string, number][] = [
      ['Files', breakdown.files],
      ['System prompt', breakdown.systemPrompt],
      ['Instructions', breakdown.instructions],
      ['Conversation', breakdown.conversation],
      ['Output reserve', breakdown.outputReservation],
    ];
    for (const [label, tokens] of entries) {
      const pct = ((tokens / snapshot.windowCapacity) * 100).toFixed(1);
      stream.markdown(`| ${label} | ~${this.fmtTokens(tokens)} | ${pct}% |\n`);
    }
    stream.markdown(`| **Total** | **~${this.fmtTokens(snapshot.totalEstimatedTokens)}** | **${snapshot.usagePercent.toFixed(1)}%** |\n\n`);

    // Per-turn history table
    if (history.length > 0) {
      stream.markdown(`### Turn History\n\n`);
      stream.markdown(`| Turn | Input | Files | Overhead | Tabs | Pinned |\n|---|---|---|---|---|---|\n`);

      for (const t of history) {
        stream.markdown(`| ${t.turn} | ~${this.fmtTokens(t.inputTokens)} | ~${this.fmtTokens(t.fileTokens)} | ~${this.fmtTokens(t.overheadTokens)} | ${t.tabCount} | ${t.pinnedCount} |\n`);
      }

      // Growth analysis
      stream.markdown(`\n### Growth Analysis\n\n`);

      const avgGrowth = history.length >= 2
        ? (history[history.length - 1].inputTokens - history[0].inputTokens) / (history.length - 1)
        : 0;

      const firstFile = history[0].fileTokens;
      const lastFile = history[history.length - 1].fileTokens;
      const fileTrend = lastFile > firstFile * 1.1 ? 'growing' : lastFile < firstFile * 0.9 ? 'shrinking' : 'stable';

      stream.markdown(`- **Conversation cost:** ~800 tokens/turn (estimated)\n`);
      if (history.length >= 2) {
        stream.markdown(`- **Input growth rate:** ~${this.fmtTokens(Math.round(avgGrowth))}/turn\n`);
      }
      stream.markdown(`- **File tokens:** ${fileTrend} (${this.fmtTokens(firstFile)} → ${this.fmtTokens(lastFile)})\n`);
      stream.markdown(`- **Output reserved:** ~${this.fmtTokens(model.maxOutput)} per response\n\n`);
    } else {
      stream.markdown(`*No turn history yet.* Use \`@tokalator /pin\`, \`/optimize\`, or \`/unpin\` to start tracking.\n\n`);
    }

    // Actionable suggestions
    const suggestions: string[] = [];

    const config = vscode.workspace.getConfiguration('tokalator');
    const threshold = config.get<number>('relevanceThreshold', 0.3);
    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
    if (distractors.length > 0) {
      const saveable = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
      suggestions.push(`Close ${distractors.length} low-relevance tabs to save ~${this.fmtTokens(saveable)} tokens`);
    }

    const turnsLeft = model.rotThreshold - snapshot.chatTurnCount;
    if (turnsLeft <= 5 && turnsLeft > 0) {
      suggestions.push(`${turnsLeft} turns until context rot threshold (${model.rotThreshold}) — consider \`/reset\``);
    } else if (turnsLeft <= 0) {
      suggestions.push(`Past context rot threshold (${model.rotThreshold} turns) — run \`/reset\` to clear`);
    }

    const inputPct = snapshot.usagePercent;
    if (inputPct >= 80) {
      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — compaction point reached`);
    } else if (inputPct >= 60) {
      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — approaching compaction point`);
    }

    const pinnedCount = snapshot.pinnedFiles.size;
    if (pinnedCount > 5) {
      suggestions.push(`${pinnedCount} files pinned — unpin files you're done with`);
    }

    if (suggestions.length > 0) {
      stream.markdown(`### Recommendations\n\n`);
      for (const s of suggestions) {
        stream.markdown(`- ${s}\n`);
      }
    } else {
      stream.markdown(`> Context looks healthy — no compaction needed yet.\n`);
    }

    return {};
  }

  /**
   * /breakdown — Where are tokens going
   */
  private async handleBreakdown(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    await this.monitor.refresh();
    const snapshot = this.monitor.getLatestSnapshot();

    if (!snapshot) {
      stream.markdown('Unable to get breakdown.');
      return {};
    }

    stream.markdown(`## Token Breakdown\n\n`);

    // Simple bar
    const barLen = 20;
    const filled = Math.round((snapshot.usagePercent / 100) * barLen);
    const bar = '█'.repeat(filled) + '░'.repeat(barLen - filled);
    stream.markdown(`\`${bar}\` ${snapshot.budgetLevel}\n\n`);

    // Top files by token usage
    const sorted = [...snapshot.tabs].sort((a, b) => b.estimatedTokens - a.estimatedTokens);

    stream.markdown(`### Largest files\n\n`);
    stream.markdown(`| File | Tokens | Relevance |\n|---|---|---|\n`);

    for (const tab of sorted.slice(0, 8)) {
      const relIcon = this.relevanceLabel(tab.relevanceScore);
      stream.markdown(`| ${tab.label} | ~${this.fmtTokens(tab.estimatedTokens)} | ${relIcon} |\n`);
    }

    // Overhead
    const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
    const overhead = snapshot.totalEstimatedTokens - fileTokens;
    stream.markdown(`| *System overhead* | ~${this.fmtTokens(overhead)} | — |\n\n`);

    // Distractors
    const config = vscode.workspace.getConfiguration('tokalator');
    const threshold = config.get<number>('relevanceThreshold', 0.3);
    const distractors = sorted.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);

    if (distractors.length > 0) {
      const distractorTokens = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
      stream.markdown(`> **${distractors.length} low-relevance files** using ~${this.fmtTokens(distractorTokens)} tokens\n`);
    }

    return {};
  }

  /**
   * Default — show help
   */
  private async handleDefault(
    request: vscode.ChatRequest,
    stream: vscode.ChatResponseStream,
  ): Promise<vscode.ChatResult> {
    await this.monitor.refresh();
    const snapshot = this.monitor.getLatestSnapshot();

    stream.markdown(`## Tokalator\n\n`);
    stream.markdown(`Count your tokens like beads on an abacus.\n\n`);
    stream.markdown(`| Command | Description |\n|---|---|\n`);
    stream.markdown(`| \`@tokalator /count\` | Current token count and budget level |\n`);
    stream.markdown(`| \`@tokalator /breakdown\` | See where tokens are going |\n`);
    stream.markdown(`| \`@tokalator /optimize\` | Close low-relevance tabs |\n`);
    stream.markdown(`| \`@tokalator /pin <file>\` | Pin a file as always-relevant |\n`);
    stream.markdown(`| \`@tokalator /unpin <file>\` | Unpin a file |\n`);
    stream.markdown(`| \`@tokalator /instructions\` | List instruction files and their token cost |\n`);
    stream.markdown(`| \`@tokalator /model [name]\` | Show or switch the active model |\n`);
    stream.markdown(`| \`@tokalator /compaction\` | Per-turn growth and compaction advice |\n`);
    stream.markdown(`| \`@tokalator /preview\` | Preview token cost before sending |\n`);
    stream.markdown(`| \`@tokalator /reset\` | Reset session (clear turn counter) |\n`);
    stream.markdown(`| \`@tokalator /exit\` | End session and save summary |\n\n`);

    if (snapshot) {
      const levelEmoji = snapshot.budgetLevel === 'low' ? '🟢'
        : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';
      stream.markdown(`**Current:** ${levelEmoji} ${snapshot.tabs.length} tabs, budget ${snapshot.budgetLevel}\n`);
    }

    return {};
  }

  /**
   * /instructions — List instruction files and their token cost
   */
  private async handleInstructions(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    stream.progress('Scanning instruction files...');

    // Find all instruction-like files
    const patterns = [
      '**/*.instructions.md',
      '**/.github/copilot-instructions.md',
      '**/.copilot/*.md',
      '**/*.prompt.md',
      '**/.cursorrules',
      '**/.claude/**/*.md',
      '**/CLAUDE.md',
      '**/AGENTS.md',
      '**/*.agent.md',
    ];

    const allFiles: { path: string; tokens: number }[] = [];

    for (const pattern of patterns) {
      try {
        const files = await vscode.workspace.findFiles(pattern, '**/node_modules/**', 50);
        for (const uri of files) {
          try {
            const doc = await vscode.workspace.openTextDocument(uri);
            const model = this.monitor.getActiveModel();
            const tokenizer = this.monitor.getTokenizer();
            const tokens = tokenizer.countTokens(doc.getText(), model.provider);
            allFiles.push({
              path: vscode.workspace.asRelativePath(uri),
              tokens,
            });
          } catch {
            allFiles.push({ path: vscode.workspace.asRelativePath(uri), tokens: 0 });
          }
        }
      } catch {
        // pattern not found
      }
    }

    if (allFiles.length === 0) {
      stream.markdown('No instruction files found in this workspace.\n\n');
      stream.markdown('Instruction files are automatically attached to AI context. Common patterns:\n\n');
      stream.markdown('| File | Used by |\n|---|---|\n');
      stream.markdown('| `.github/copilot-instructions.md` | GitHub Copilot |\n');
      stream.markdown('| `*.instructions.md` | GitHub Copilot |\n');
      stream.markdown('| `*.prompt.md` | Copilot / Claude |\n');
      stream.markdown('| `AGENTS.md` | Claude Code |\n');
      stream.markdown('| `.cursorrules` | Cursor |\n');
      return {};
    }

    // Sort by tokens descending
    allFiles.sort((a, b) => b.tokens - a.tokens);
    const totalTokens = allFiles.reduce((sum, f) => sum + f.tokens, 0);

    stream.markdown(`## Instruction Files\n\n`);
    stream.markdown(`**${allFiles.length} files** using ~${this.fmtTokens(totalTokens)} tokens\n\n`);
    stream.markdown(`| File | Tokens |\n|---|---|\n`);

    for (const f of allFiles) {
      stream.markdown(`| \`${f.path}\` | ~${this.fmtTokens(f.tokens)} |\n`);
    }

    const model = this.monitor.getActiveModel();
    const pct = ((totalTokens / model.contextWindow) * 100).toFixed(1);
    stream.markdown(`\n> Instructions use **${pct}%** of ${model.label}'s ${this.fmtTokens(model.contextWindow)} context window\n`);

    return {};
  }

  /**
   * /model — Show or switch the active model
   */
  private async handleModel(
    request: vscode.ChatRequest,
    stream: vscode.ChatResponseStream,
  ): Promise<vscode.ChatResult> {
    const query = request.prompt.trim();
    const currentModel = this.monitor.getActiveModel();

    if (!query) {
      // Show current model and list all
      stream.markdown(`## Active Model: ${currentModel.label}\n\n`);
      stream.markdown(`| | |\n|---|---|\n`);
      const tokenizer = this.monitor.getTokenizer();
      stream.markdown(`| **Context window** | ${this.fmtTokens(currentModel.contextWindow)} |\n`);
      stream.markdown(`| **Max output** | ${this.fmtTokens(currentModel.maxOutput)} |\n`);
      stream.markdown(`| **Tokenizer** | ${tokenizer.getTokenizerLabel(currentModel.provider)} |\n`);
      stream.markdown(`| **Rot threshold** | ${currentModel.rotThreshold} turns |\n`);
      stream.markdown(`| **Provider** | ${currentModel.provider} |\n\n`);

      stream.markdown(`### Available Models\n\n`);
      const models = this.monitor.getModels();
      for (const m of models) {
        const active = m.id === currentModel.id ? ' ← active' : '';
        stream.markdown(`- **${m.label}** — ${this.fmtTokens(m.contextWindow)}${active}\n`);
      }
      stream.markdown(`\nSwitch with: \`@tokalator /model claude sonnet 4.5\`\n`);
      return {};
    }

    // Try to find matching model
    const match = findModel(query);

    if (!match) {
      stream.markdown(`No model matching "${query}". Try \`@tokalator /model\` to see all options.\n`);
      return {};
    }

    this.monitor.setModel(match.id);
    stream.markdown(`Switched to **${match.label}**\n\n`);
    stream.markdown(`| | |\n|---|---|\n`);
    stream.markdown(`| **Context window** | ${this.fmtTokens(match.contextWindow)} |\n`);
    stream.markdown(`| **Max output** | ${this.fmtTokens(match.maxOutput)} |\n`);
    stream.markdown(`| **Rot threshold** | ${match.rotThreshold} turns |\n`);

    return {};
  }

  private fmtTokens(n: number): string {
    return n >= 1000 ? (n / 1000).toFixed(1) + 'K' : n.toString();
  }

  private relevanceLabel(score: number): string {
    if (score >= 0.6) { return 'high'; }
    if (score >= 0.3) { return 'med'; }
    return 'low';
  }

  private stripQuotes(value: string): string {
    if (value.length >= 2) {
      const first = value[0];
      const last = value[value.length - 1];
      if (first === last && ['"', "'", '`'].includes(first)) {
        return value.slice(1, -1);
      }
    }
    return value;
  }

  private async resolveUrisFromInput(input: string): Promise<vscode.Uri[]> {
    const normalized = this.normalizeInputPath(input);
    if (!normalized) { return []; }

    if (this.isAbsolutePath(normalized)) {
      const absoluteUri = vscode.Uri.file(normalized);
      if (await this.fileExists(absoluteUri)) {
        return [absoluteUri];
      }
    }

    const relativeUri = await this.tryResolveRelative(normalized);
    if (relativeUri) {
      return [relativeUri];
    }

    return this.searchWorkspace(normalized);
  }

  private normalizeInputPath(value: string): string {
    if (!value) { return ''; }
    const expanded = value.startsWith('~')
      ? path.join(os.homedir(), value.slice(1))
      : value;
    return path.normalize(expanded);
  }

  private isAbsolutePath(p: string): boolean {
    return path.isAbsolute(p) || /^[A-Za-z]:[\\/]/.test(p);
  }

  private async tryResolveRelative(relativePath: string): Promise<vscode.Uri | null> {
    const trimmed = relativePath.replace(/^(\.\\|\.\/)+/, '').replace(/^\\+|^\/+/, '');
    if (!trimmed) { return null; }
    const folders = vscode.workspace.workspaceFolders || [];
    for (const folder of folders) {
      const candidate = vscode.Uri.file(path.join(folder.uri.fsPath, trimmed));
      if (await this.fileExists(candidate)) {
        return candidate;
      }
    }
    return null;
  }

  private async searchWorkspace(target: string): Promise<vscode.Uri[]> {
    const globTarget = target.replace(/^[/\\]+/, '').replace(/\\/g, '/');
    if (!globTarget) { return []; }
    try {
      return await vscode.workspace.findFiles(`**/${globTarget}`, '**/node_modules/**', 5);
    } catch {
      return [];
    }
  }

  private async fileExists(uri: vscode.Uri): Promise<boolean> {
    try {
      const stat = await vscode.workspace.fs.stat(uri);
      return stat.type === vscode.FileType.File;
    } catch {
      return false;
    }
  }

  private dedupeUris(uris: vscode.Uri[]): vscode.Uri[] {
    const seen = new Set<string>();
    const unique: vscode.Uri[] = [];
    for (const uri of uris) {
      const key = uri.toString();
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(uri);
      }
    }
    return unique;
  }

  /**
   * Auto-detect the model from the Copilot chat request and sync Tokalator to it.
   * Tries to match by family → id → name so switching models in the Copilot UI
   * automatically updates context window and tokenizer without any manual step.
   */
  private async syncModelFromRequest(request: vscode.ChatRequest): Promise<void> {
    const lm = request.model;
    if (!lm) { return; }

    const current = this.monitor.getActiveModel();
    // Try family first (most stable identifier), then full id, then display name
    const match = findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name);

    if (match && match.id !== current.id) {
      await this.monitor.setModel(match.id);
    }
  }

  dispose(): void {
    this.participant.dispose();
  }
}

