{
  "name": "@Tokalator",
  "version": "v3.1.2",
  "footer": "\u00a9 2026 @Tokalator. Made by Vahid Faraji with love from Istanbul.",
  "github": "https://github.com/vfaraji89/tokalator",
  "authorGithub": "https://github.com/vfaraji89",
