} from 'recharts';
import { PROVIDER_MODELS } from '@/lib/providers';

const P = {
  red: '#e3120b', black: '#111', white: '#fff',
  g1: '#f3f3f3', g3: '#ccc', g5: '#888', g7: '#555',
};
