                    background: COLORS.tooltip,
                    border: '1px solid #333',
                    borderRadius: 0,
                    fontSize: 12,
                  }}
                  formatter={(value) => [`$${Number(value).toFixed(2)}/MTok`, '']}
                />
                <Legend 
                  wrapperStyle={{ fontSize: 11, paddingTop: 20 }}
                />
                <Line
                  type="monotone"
                  dataKey="claude-opus-4.6"
                  name="Claude Opus 4.6"
                  stroke={COLORS.anthropic}
                  strokeWidth={2}
                  dot={false}
                />
                <Line
                  type="monotone"
                  dataKey="gpt-5.2"
                  name="GPT-5.2"
                  stroke="#666"
                  strokeWidth={2}
                  dot={false}
                />
                <Line
                  type="monotone"
                  dataKey="gemini-3-pro"
