     1→"use client";
     2→
     3→import { useState, useEffect, useRef } from "react";
     4→
     5→const COMMANDS = [
     6→  "/count",
     7→  "/optimize",
     8→  "/preview",
     9→  "/breakdown",
    10→  "/pin",
    11→  "/unpin",
    12→  "/model",
    13→  "/compaction",
    14→  "/instructions",
    15→  "/reset",
    16→  "/exit",
    17→];
    18→
    19→const MENTION = "@tokalator";
    20→const TYPING_SPEED = 65;      // ms per character
    21→const PAUSE_AFTER = 1800;     // ms to hold the completed command
    22→const DELETE_SPEED = 30;       // ms per character when erasing
    23→const PAUSE_BEFORE = 400;     // ms before typing next command
    24→
    25→export function CommandTyper() {
    26→  const [cmdIndex, setCmdIndex] = useState(0);
    27→  const [charIndex, setCharIndex] = useState(0);
    28→  const [deleting, setDeleting] = useState(false);
    29→  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    30→
    31→  const currentCmd = COMMANDS[cmdIndex];
    32→
    33→  useEffect(() => {
    34→    if (!deleting) {
    35→      // Typing forward
    36→      if (charIndex < currentCmd.length) {
    37→        timeoutRef.current = setTimeout(() => {
    38→          setCharIndex((c) => c + 1);
    39→        }, TYPING_SPEED);
    40→      } else {
    41→        // Finished typing — pause, then start deleting
    42→        timeoutRef.current = setTimeout(() => {
    43→          setDeleting(true);
    44→        }, PAUSE_AFTER);
    45→      }
    46→    } else {
    47→      // Deleting
    48→      if (charIndex > 0) {
    49→        timeoutRef.current = setTimeout(() => {
    50→          setCharIndex((c) => c - 1);
    51→        }, DELETE_SPEED);
    52→      } else {
    53→        // Finished deleting — move to next command
    54→        timeoutRef.current = setTimeout(() => {
    55→          setDeleting(false);
    56→          setCmdIndex((i) => (i + 1) % COMMANDS.length);
    57→        }, PAUSE_BEFORE);
    58→      }
    59→    }
    60→
    61→    return () => {
    62→      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    63→    };
    64→  }, [charIndex, deleting, currentCmd]);
    65→
    66→  const visibleCmd = currentCmd.slice(0, charIndex);
    67→
    68→  return (
    69→    <div className="command-typer" aria-live="polite" aria-label="Chat command demo">
    70→      <span className="command-typer-mention">{MENTION}</span>
    71→      <span className="command-typer-space"> </span>
    72→      <span className="command-typer-cmd">{visibleCmd}</span>
    73→      <span className="command-typer-cursor" aria-hidden>|</span>
    74→    </div>
    75→  );
    76→}
