    10→const P = { red: "#e3120b", black: "#111", g7: "#555", g5: "#888", g3: "#ccc", g1: "#f3f3f3", white: "#fff" };
    11→const tt = { contentStyle: { background: P.white, border: `1px solid ${P.g3}`, borderRadius: 4, fontSize: 12, color: P.black } };
    12→const fmtTok = (n: number) => n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${(n / 1000).toFixed(0)}K` : String(n);
    13→
    14→// ── Types ──
    15→
    16→interface UsageRecord {
    17→  id: string;
    18→  date: string;
    19→  model: string;
    20→  provider: string;
    21→  project: string;
    22→  inputTokens: number;
    23→  outputTokens: number;
    24→  cacheWriteTokens: number;
    25→  cacheReadTokens: number;
    26→  cost: number;
    27→}
    28→
    29→// ── Pricing for client-side cost estimation ──
    30→
    31→const PRICING: Record<string, [number, number]> = {
    32→  "claude-opus-4.6": [5.0, 25.0], "claude-sonnet-4.5": [3.0, 15.0], "claude-haiku-4.5": [1.0, 5.0],
    33→  "gpt-5.2": [1.75, 14.0], "gpt-5.2-codex": [0.50, 4.0], "gpt-5.1": [2.50, 10.0],
    34→  "gpt-4.1": [3.0, 12.0], "gpt-4.1-mini": [0.80, 3.20], "gpt-4.1-nano": [0.20, 0.80],
    35→  "gpt-5-mini": [0.25, 2.0], "o4-mini": [4.0, 16.0], "gpt-4o": [2.50, 10.0],
    36→  "gemini-3-pro": [2.0, 12.0], "gemini-3-flash": [0.50, 3.0], "gemini-2.5-pro": [1.25, 10.0],
    37→  "gemini-2.5-flash": [0.30, 2.50], "gemini-2.5-flash-lite": [0.10, 0.40], "gemini-2.0-flash": [0.10, 0.40],
    38→};
    39→
    40→function estimateCost(model: string, inp: number, out: number): number {
    41→  const key = model.toLowerCase().trim();
    42→  let prices = PRICING[key];
    43→  if (!prices) {
    44→    for (const [k, v] of Object.entries(PRICING)) {
    45→      if (k.includes(key) || key.includes(k)) { prices = v; break; }
    46→    }
    47→  }
    48→  if (!prices) prices = [3.0, 15.0];
    49→  return (inp / 1_000_000) * prices[0] + (out / 1_000_000) * prices[1];
    50→}
    51→
