    54→const PROVIDER_COLORS: Record<string, string> = {
    55→  anthropic: P.black, openai: "#10a37f", google: "#4285f4", unknown: P.g5,
    56→};
    57→
    58→function detectProvider(model: string): string {
    59→  const m = model.toLowerCase();
    60→  if (m.includes("claude")) return "anthropic";
    61→  if (m.includes("gpt") || m.startsWith("o")) return "openai";
    62→  if (m.includes("gemini")) return "google";
    63→  return "unknown";
    64→}
    65→
    66→// ── Client-side CSV parser ──
    67→
    68→function parseCSVClientSide(text: string): { records: UsageRecord[]; warnings: string[] } {
    69→  const lines = text.trim().split("\n");
    70→  if (lines.length < 2) return { records: [], warnings: ["CSV has no data rows"] };
    71→
    72→  const headers = lines[0].split(",").map(h => h.trim().toLowerCase().replace(/['"]/g, ""));
    73→
    74→  const findCol = (candidates: string[]): number => {
    75→    for (const c of candidates) {
    76→      const idx = headers.indexOf(c);
    77→      if (idx >= 0) return idx;
    78→    }
    79→    return -1;
