  // Caching break-even
  const cachingCalc = useMemo(() => {
    const prices = CACHE_PRICING[cacheModel] || [3.0, 3.75, 0.30];
    const [inputPrice, cwPrice, crPrice] = prices;
    const cached = Math.min(cachePortion, cacheInput);
