@import "tailwindcss";

:root {
  --font-primary: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "SF Mono", ui-monospace, SFMono-Regular, "Cascadia Code", monospace;

  /* Clean black/grey/red palette */
  --black: #000000;
  --grey-900: #111111;
  --grey-800: #1a1a1a;
  --grey-700: #333333;
  --grey-600: #555555;
  --grey-500: #777777;
  --grey-400: #999999;
  --grey-300: #bbbbbb;
  --grey-200: #dddddd;
  --grey-100: #f0f0f0;
  --grey-50: #f8f8f8;
  --white: #ffffff;
  --red: #e3120b;
  --red-light: rgba(227, 18, 11, 0.08);

  /* Semantic tokens */
  --bg: var(--white);
  --bg-subtle: var(--grey-50);
  --bg-muted: var(--grey-100);
  --border: var(--grey-200);
  --border-strong: var(--grey-300);
  --text-primary: var(--black);
  --text-secondary: var(--grey-600);
  --text-muted: var(--grey-400);
  --accent: var(--red);
  --accent-bg: var(--red-light);
}

@theme inline {
  --color-background: var(--bg);
  --color-foreground: var(--text-primary);
  --font-sans: var(--font-primary);
}

* { box-sizing: border-box; }

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background: var(--bg);
  color: var(--text-primary);
  font-family: var(--font-primary);
  font-weight: 400;
  line-height: 1.6;
  margin: 0;
  padding: 0;
  font-size: 0.875rem;
}

/* Typography */
h1, h2, h3, h4 {
  font-family: var(--font-primary);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.3;
  margin: 0;
  color: var(--text-primary);
}

h1 { font-size: 1.25rem; }
h2 { font-size: 1rem; margin-bottom: 0.75rem; }
h3 { font-size: 0.875rem; font-weight: 500; }
h4 { font-size: 0.8125rem; font-weight: 500; }

p { margin: 0; color: var(--text-secondary); line-height: 1.7; }

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

code {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  background: var(--bg-muted);
  padding: 0.15em 0.4em;
  border-radius: 4px;
  color: var(--text-primary);
}

pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--grey-900);
  color: var(--grey-100);
  border-radius: 8px;
  padding: 1rem 1.25rem;
  overflow-x: auto;
  margin: 0;
}

/* ─── Page Load Animations ─── */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-12px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

html, body {
  overflow-x: hidden;
  width: 100%;
}

@keyframes shimmer {
  from { background-position: -200% center; }
  to { background-position: 200% center; }
}

/* Article entrance */
.article {
  animation: fadeIn 0.4s ease-out both;
  max-width: 100%;
  box-sizing: border-box;
  overflow-wrap: break-word;
  word-wrap: break-word;
}

/* Hero stagger — animations applied in the Hero layout section below */

/* Section entrance — staggered */
.article > section {
  animation: fadeInUp 0.5s ease-out both;
}

.article > section:nth-child(2) { animation-delay: 0.1s; }
.article > section:nth-child(3) { animation-delay: 0.15s; }
.article > section:nth-child(4) { animation-delay: 0.2s; }
.article > section:nth-child(5) { animation-delay: 0.25s; }
.article > section:nth-child(6) { animation-delay: 0.3s; }
.article > section:nth-child(7) { animation-delay: 0.35s; }

/* Cards & grid items — stagger children */
.feature-grid > *,
.tool-grid > *,
.wiki-grid > *,
.why-stats > * {
  animation: scaleIn 0.35s ease-out both;
}

.feature-grid > *:nth-child(1),
.tool-grid > *:nth-child(1),
.wiki-grid > *:nth-child(1),
.why-stats > *:nth-child(1) { animation-delay: 0.1s; }

.feature-grid > *:nth-child(2),
.tool-grid > *:nth-child(2),
.wiki-grid > *:nth-child(2),
.why-stats > *:nth-child(2) { animation-delay: 0.18s; }

.feature-grid > *:nth-child(3),
.tool-grid > *:nth-child(3),
.wiki-grid > *:nth-child(3),
.why-stats > *:nth-child(3) { animation-delay: 0.26s; }

.feature-grid > *:nth-child(4),
.tool-grid > *:nth-child(4),
.wiki-grid > *:nth-child(4) { animation-delay: 0.34s; }

/* Stat numbers pulse */
.why-stat-number {
  background: linear-gradient(90deg, var(--accent), var(--text-primary), var(--accent));
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: shimmer 3s linear infinite;
}


/* Reduce motion for accessibility */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    transition-duration: 0.01ms !important;
  }
}

/* Layout */
.layout { 
  display: flex; 
  min-height: 100vh;
  max-width: 100vw;
  overflow-x: hidden;
}

.sidebar {
  width: 250px;
  border-right: 1px solid var(--border);
  padding: 1.5rem 0;
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  overflow-y: auto;
  background: var(--bg);
  z-index: 100;
  animation: slideInLeft 0.35s ease-out both;
  display: flex;
  flex-direction: column;
}

.main-content {
  flex: 1;
  margin-left: 250px;
  padding: 2rem 3rem;
  max-width: 960px;
  box-sizing: border-box;
  overflow-x: hidden;
}

/* ── Demo Mockup ─────────────────────────────── */
.demo-mockup-wrapper {
  position: relative;
  max-width: 720px;
  margin: 3rem auto 0;
  border-radius: 10px;
  overflow: visible;
  box-shadow:
    0 4px 24px rgba(0,0,0,0.10),
    0 1px 4px rgba(0,0,0,0.06);
  border: 1px solid var(--grey-200);
  background: var(--white);
  animation: demoFadeUp 0.8s ease-out both;
  animation-delay: 0.4s;
}

@keyframes demoFadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Chrome bar */
.demo-chrome {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--grey-50);
  border-bottom: 1px solid var(--grey-200);
  border-radius: 10px 10px 0 0;
}

.demo-dots {
  display: flex;
  gap: 5px;
}
.demo-dots span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.demo-url {
  flex: 1;
  text-align: center;
  font-size: 10px;
  color: var(--grey-400);
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

/* Body: sidebar + editor */
.demo-body {
  display: flex;
  min-height: 220px;
}

/* File explorer column */
.demo-sidebar {
  position: relative;
  width: 120px;
  flex-shrink: 0;
  padding: 10px;
  border-right: 1px solid var(--grey-200);
  background: var(--grey-50);
}

/* Chat / Claude Code panel */
.demo-chat-panel {
  position: relative;
  width: 170px;
  flex-shrink: 0;
  border-left: 1px solid var(--grey-200);
  background: var(--white);
  display: flex;
  flex-direction: column;
}

/* Budget fill animation */
.demo-budget-fill {
  animation: budgetGrow 1.6s ease-out both;
  animation-delay: 1s;
}
@keyframes budgetGrow {
  from { width: 0%; }
  to   { width: 68%; }
}

/* Editor area */
.demo-editor {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Tabs */
.demo-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--grey-200);
  background: var(--grey-50);
}
.demo-tab {
  padding: 5px 12px;
  font-size: 9px;
  font-family: var(--font-mono);
  color: var(--grey-400);
  border-right: 1px solid var(--grey-200);
  cursor: default;
}
.demo-tab--active {
  background: var(--white);
  color: var(--grey-900);
  border-bottom: 2px solid var(--accent);
}

/* Code area */
.demo-code {
  position: relative;
  flex: 1;
  padding: 8px 0;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.7;
}

.demo-code-line {
  display: flex;
  gap: 10px;
  padding: 0 10px;
}
.demo-code-line:nth-child(5) {
  background: rgba(227, 18, 11, 0.04);
}

.demo-line-num {
  color: var(--grey-300);
  width: 14px;
  text-align: right;
  flex-shrink: 0;
  user-select: none;
}

/* Status bar toolbar */
.demo-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--grey-900);
  border-radius: 0 0 10px 10px;
  padding: 3px 10px;
}
.demo-toolbar-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--grey-300);
  font-size: 8px;
  cursor: default;
  transition: color 0.15s;
}
.demo-toolbar-btn:hover {
  color: var(--white);
}

/* ── Demo Annotations Legend ──────────────── */
.demo-legend {
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-top: 2rem;
  flex-wrap: wrap;
}
.demo-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--grey-600);
}
.demo-legend-num {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent);
  color: white;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* Mobile responsive */
@media (max-width: 768px) {
  .sidebar {
    display: none !important;
    width: 0 !important;
  }

  .layout {
    display: block;
  }

  .main-content {
    margin-left: 0 !important;
    padding: 1rem 1rem;
    min-width: 0;
    max-width: 100vw;
    width: 100%;
    overflow-x: hidden;
    box-sizing: border-box;
  }

  .article {
    max-width: 100%;
    overflow-x: hidden;
    word-wrap: break-word;
    overflow-wrap: break-word;
  }

  .mobile-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.625rem 1rem;
    border-bottom: 2px solid var(--accent);
    position: sticky;
    top: 0;
    background: var(--grey-900);
    z-index: 100;
  }

  .mobile-logo {
    display: flex;
    align-items: center;
    gap: 0;
    text-decoration: none;
  }

  .mobile-logo:hover {
    text-decoration: none;
  }

  .mobile-logo-at {
    font-weight: 800;
    font-size: 1.25rem;
    color: var(--accent);
    letter-spacing: -0.04em;
  }

  .mobile-logo-text {
    font-weight: 700;
    font-size: 1.125rem;
    color: var(--white);
    letter-spacing: -0.03em;
  }

  /* Hamburger / close button */
  .mobile-menu-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: none;
    background: transparent;
    color: var(--white);
    cursor: pointer;
    border-radius: 6px;
    transition: background 0.15s;
  }
  .mobile-menu-btn:hover {
    background: rgba(255,255,255,0.08);
  }

  /* Overlay behind menu */
  .mobile-overlay {
    position: fixed;
    inset: 0;
    top: 47px; /* below header */
    background: rgba(0,0,0,0.5);
    z-index: 90;
    animation: overlayIn 0.2s ease-out;
  }
  @keyframes overlayIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  /* Slide-down mobile menu */
  .mobile-menu {
    position: fixed;
    top: 47px;
    left: 0;
    right: 0;
    max-height: 0;
    overflow: hidden;
    background: var(--grey-900);
    z-index: 95;
    transition: max-height 0.3s ease, box-shadow 0.3s ease;
    border-bottom: 2px solid transparent;
  }
  .mobile-menu--open {
    max-height: 80vh;
    overflow-y: auto;
    border-bottom: 2px solid var(--accent);
    box-shadow: 0 8px 32px rgba(0,0,0,0.3);
  }

  .mobile-menu-section {
    padding: 0.5rem 0;
    border-bottom: 1px solid rgba(255,255,255,0.06);
  }
  .mobile-menu-section:last-of-type {
    border-bottom: none;
  }

  .mobile-menu-section-label {
    padding: 0.25rem 1.25rem;
    font-size: 0.5625rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--grey-500);
  }

  .mobile-menu-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1.25rem;
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--grey-300);
    text-decoration: none;
    transition: background 0.15s, color 0.15s;
  }
  .mobile-menu-link:hover {
    background: rgba(255,255,255,0.04);
    color: var(--white);
    text-decoration: none;
  }
  .mobile-menu-link--active {
    color: var(--white);
    background: rgba(227,18,11,0.08);
    border-left: 3px solid var(--accent);
    font-weight: 600;
  }

  .mobile-menu-footer {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border-top: 1px solid rgba(255,255,255,0.06);
  }
  .mobile-menu-version {
    font-size: 0.625rem;
    color: var(--grey-500);
  }
  .mobile-menu-footer .sidebar-github-link {
    color: var(--grey-400);
  }
  .mobile-menu-footer .sidebar-github-link:hover {
    color: var(--white);
  }

  .overlay {
    display: none;
  }

  .mobile-desktop-hint {
    display: none;
  }

  .mobile-logo-icon {
    display: none;
  }

  /* Demo mockup mobile */
  .demo-mockup-wrapper { margin: 2rem auto 0; max-width: 100%; }
  .demo-sidebar { width: 100px; padding: 8px; }
  .demo-chat-panel { width: 140px; }
  .demo-code { font-size: 8px; }
  .demo-tab { padding: 4px 8px; font-size: 8px; }
  .demo-legend { gap: 1rem; margin-top: 1.5rem; }
  .demo-legend-item { font-size: 11px; }

  /* ── Learn page mobile ── */
  .learn-frame {
    margin: 1rem 0;
    border-radius: 8px;
  }

  .learn-lesson {
    margin-bottom: 2rem;
  }

  .learn-lesson-title {
    font-size: 1.0625rem;
  }

  .learn-lesson-desc {
    font-size: 0.8125rem;
  }

  .learn-window-visual {
    padding: 12px;
  }

  .learn-window-segments {
    height: 40px;
  }

  .learn-segment-label {
    font-size: 0.45rem;
  }

  .learn-segment-pct {
    font-size: 0.5rem;
  }

  .learn-window-meta {
    flex-wrap: wrap;
    gap: 0.75rem;
    font-size: 0.6875rem;
  }

  .learn-code-pre {
    font-size: 0.625rem;
    line-height: 1.6;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .learn-code-line {
    gap: 0.5rem;
    padding: 0 0.5rem;
  }

  .learn-compact-visual {
    gap: 0.75rem;
    padding: 12px;
  }

  .learn-compact-col {
    max-width: 100px;
  }

  .learn-compact-val {
    font-size: 0.5rem;
  }

  .learn-compact-strategies {
    grid-template-columns: 1fr;
    padding: 0 12px 12px;
    font-size: 0.625rem;
  }

  .learn-frame-pad {
    padding: 12px;
  }

  .learn-turns-row {
    gap: 4px;
    flex-wrap: wrap;
  }

  .learn-side-by-side {
    flex-direction: column;
    gap: 12px;
  }

  .learn-side-by-side > div {
    width: 100%;
  }

  .learn-side-by-side > div > svg {
    transform: rotate(90deg);
  }

  .learn-compare-table {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .learn-compare-table table {
    font-size: 0.6875rem;
    min-width: 400px;
  }

  .learn-compare-table th,
  .learn-compare-table td {
    padding: 7px 10px;
  }

  .learn-nav {
    padding: 1rem;
  }

  .learn-nav-item {
    padding: 0.625rem 0.75rem;
  }

  .learn-badge {
    font-size: 0.5rem;
  }
}

@media (min-width: 769px) {
  .mobile-header,
  .mobile-desktop-hint,
  .mobile-menu,
  .mobile-overlay,
  .overlay {
    display: none !important;
  }
}

/* Sidebar */
.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.25rem;
  margin-bottom: 1.5rem;
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 0.125rem;
  text-decoration: none;
}

.sidebar-at {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--accent);
  margin-right: 0.0625rem;
}

.sidebar-logo-text {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.03em;
}

.sidebar-version {
  font-size: 0.625rem;
  font-weight: 600;
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 9999px;
  padding: 0.1em 0.5em;
}

.sidebar-footer {
  margin-top: auto;
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--border);
}

.sidebar-footer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.sidebar-github-link {
  display: flex;
  align-items: center;
  color: var(--text-muted);
  transition: color 0.15s ease;
}
.sidebar-github-link:hover {
  color: var(--text-primary);
}

.sidebar-made-by {
  font-size: 0.6875rem;
  color: var(--text-muted);
  line-height: 1.5;
}
.sidebar-made-by a {
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
}
.sidebar-made-by a:hover {
  color: var(--accent);
  text-decoration: underline;
}
.sidebar-heart {
  display: inline-block;
  font-size: 1.1em;
  color: var(--accent);
  transition: transform 0.3s ease, color 0.3s ease;
}

.sidebar-heart.heart-active {
  animation: heartBeat 1.2s ease-in-out infinite, heartColors 3s ease-in-out infinite;
}

/* Update Pill */
.update-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 0.8125rem;
  color: var(--text-secondary);
  text-decoration: none;
  transition: border-color 0.2s, color 0.2s;
  margin-bottom: 1.25rem;
}
.update-pill:hover {
  border-color: var(--accent);
  color: var(--text-primary);
}
.update-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}
.update-arrow {
  color: var(--text-muted);
  transition: transform 0.2s;
}
.update-pill:hover .update-arrow {
  transform: translateX(2px);
}

/* Coming Soon Badge */
.coming-soon-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--accent);
  background: var(--accent-bg);
  border: 1px solid var(--accent);
  border-radius: 9999px;
  padding: 0.25em 0.75em;
  animation: pulse-badge 2s ease-in-out infinite;
}

@keyframes pulse-badge {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

.cta-disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

.nav-section-label {
  margin-top: 2rem;
  padding: 0.75rem 1.25rem 0.5rem;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
  border-top: 1px solid var(--border);
}

.nav-section-label:first-of-type {
  border-top: none;
  margin-top: 0;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 400;
  color: var(--text-secondary);
  transition: all 0.2s ease;
  text-decoration: none;
  border-left: 3px solid transparent;
  border-radius: 0 6px 6px 0;
}

.nav-link:hover {
  color: var(--text-primary);
  background: var(--bg-subtle);
  border-left-color: var(--grey-300);
  text-decoration: none;
  box-shadow: 0 2px 12px rgba(227, 18, 11, 0.12), 0 0 0 1px rgba(227, 18, 11, 0.06);
}

.nav-link.active {
  color: var(--text-primary);
  font-weight: 600;
  background: var(--bg-muted);
  border-left-color: var(--accent);
  box-shadow: 0 2px 8px rgba(227, 18, 11, 0.10);
}

/* Collapsible nav section toggle */
.nav-section-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
  color: var(--text-muted);
  transition: color 0.15s ease;
}
.nav-section-toggle:hover {
  color: var(--text-secondary);
}

/* Nested submenu */
.nav-submenu {
  animation: navSlideIn 0.2s ease-out;
}
.nav-link--nested {
  padding-left: 1.75rem;
  font-size: 0.775rem;
  border-left: 1px solid var(--grey-200);
  margin-left: 1.25rem;
  border-radius: 0;
}
.nav-link--nested.active {
  border-left-color: var(--accent);
}

@keyframes navSlideIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.nav-icon {
  font-size: 0.75rem;
  width: 1rem;
  text-align: center;
  flex-shrink: 0;
}

.nav-badge {
  font-size: 0.5625rem;
  font-weight: 600;
  background: var(--accent-bg);
  color: var(--accent);
  padding: 0.15em 0.5em;
  border-radius: 4px;
  margin-left: 0.5rem;
}

/* Article */
.article {
  max-width: 720px;
}

.article header {
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border);
}

.article .tagline {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
  margin-top: 0.5rem;
}

/* Hero */
.hero {
  margin-bottom: 2.5rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border);
  animation: fadeInUp 0.5s ease-out both;
}

.hero-icon {
  font-size: 2.5rem;
  margin-bottom: 0.75rem;
  animation: scaleIn 0.4s ease-out 0.15s both;
}

/* Motionable outline icon — Agentation-inspired */
.hero-outline-icon {
  margin-bottom: 1rem;
  animation: fadeInUp 0.4s ease-out both;
}

.hero-abacus {
  color: var(--grey-700);
  transition: color 0.3s ease;
}

.hero-outline-icon:hover .hero-abacus {
  color: var(--accent);
}

/* Bead idle motion */
@keyframes beadSlide1 { 0%, 30% { transform: translateX(0); } 35%, 55% { transform: translateX(4px); } 60%, 100% { transform: translateX(0); } }
@keyframes beadSlide2 { 0%, 40% { transform: translateX(0); } 45%, 65% { transform: translateX(-3px); } 70%, 100% { transform: translateX(0); } }
@keyframes beadSlide3 { 0%, 55% { transform: translateX(0); } 60%, 80% { transform: translateX(5px); } 85%, 100% { transform: translateX(0); } }

.hero-bead {
  fill: var(--grey-500);
  transition: fill 0.3s ease;
}
.hero-bead-1, .hero-bead-4, .hero-bead-6, .hero-bead-7 { fill: var(--accent); }
.hero-bead-1, .hero-bead-2 { animation: beadSlide1 4s ease-in-out 0.5s infinite; }
.hero-bead-3, .hero-bead-4, .hero-bead-5 { animation: beadSlide2 4s ease-in-out 0.5s infinite; }
.hero-bead-6, .hero-bead-7, .hero-bead-8 { animation: beadSlide3 4s ease-in-out 0.5s infinite; }

.hero-outline-icon:hover .hero-bead { fill: var(--accent); }
.hero-outline-icon:hover .hero-bead-2,
.hero-outline-icon:hover .hero-bead-3,
.hero-outline-icon:hover .hero-bead-8 { fill: var(--grey-700); }

/* Marker highlight on first line — Agentation-style red marker */
.hero-marker {
  position: relative;
  display: inline;
}

.hero-marker::after {
  content: "";
  position: absolute;
  left: -4px;
  right: -4px;
  bottom: 0;
  height: 40%;
  background: rgba(227, 18, 11, 0.12);
  border-radius: 3px;
  z-index: -1;
  animation: markerReveal 0.6s ease-out 0.3s both;
}

@keyframes markerReveal {
  0% { transform: scaleX(0); transform-origin: left; }
  100% { transform: scaleX(1); transform-origin: left; }
}

/* Underline on second line */
.hero-underline {
  position: relative;
  display: inline;
}

.hero-underline::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
  animation: markerReveal 0.5s ease-out 0.5s both;
}

/* @Tokalator text-motion animation */
@keyframes textMotionReveal {
  0% { clip-path: inset(0 100% 0 0); opacity: 0; }
  30% { opacity: 1; }
  100% { clip-path: inset(0 0 0 0); opacity: 1; }
}

@keyframes textMotionGlow {
  0%, 100% { text-shadow: none; }
  50% { text-shadow: 0 0 8px rgba(227, 18, 11, 0.25); }
}

.text-motion {
  display: inline-block;
  animation: textMotionReveal 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
             textMotionGlow 3s ease-in-out 1s infinite;
}

.text-motion:hover {
  text-shadow: 0 0 12px rgba(227, 18, 11, 0.3);
}

.hero-headline {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 1rem;
  animation: fadeInUp 0.5s ease-out 0.1s both;
}

.hero-description {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
  animation: fadeInUp 0.5s ease-out 0.2s both;
}

.accent-highlight {
  color: var(--accent);
  background: var(--accent-bg);
  padding: 0.1em 0.4em;
  border-radius: 4px;
  font-weight: 600;
  animation: scaleIn 0.4s ease-out 0.25s both;
}

.hero-ctas {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
  animation: fadeInUp 0.4s ease-out 0.3s both;
}

.cta-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.5rem;
  background: var(--accent);
  color: var(--white);
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: 8px;
  text-decoration: none;
  transition: all 0.15s ease;
  border: 1px solid var(--accent);
}

.cta-primary:hover {
  background: #c40e08;
  border-color: #c40e08;
  text-decoration: none;
}

.cta-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.5rem;
  background: var(--bg);
  color: var(--text-primary);
  font-weight: 500;
  font-size: 0.875rem;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  text-decoration: none;
  transition: all 0.15s ease;
}

.cta-secondary:hover {
  border-color: var(--text-primary);
  text-decoration: none;
}

.install-cmd {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--grey-900);
  border-radius: 8px;
  padding: 0.5rem 0.75rem;
  animation: fadeInUp 0.4s ease-out 0.4s both;
}

.install-cmd code {
  background: none;
  color: var(--grey-100);
  padding: 0;
  font-size: 0.8125rem;
}

/* Command Typer — typewriter animation below install */
.command-typer {
  display: inline-flex;
  align-items: center;
  gap: 0;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: var(--text-muted);
  padding: 0.5rem 0.875rem;
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-top: 0.75rem;
  margin-bottom: 0.25rem;
  animation: fadeInUp 0.4s ease-out 0.5s both;
  min-height: 2.125rem;
}

.command-typer-mention {
  color: var(--accent);
  font-weight: 700;
}

.command-typer-space {
  white-space: pre;
}

.command-typer-cmd {
  color: var(--text-primary);
  font-weight: 500;
  min-width: 0;
}

.command-typer-cursor {
  color: var(--accent);
  font-weight: 300;
  animation: cursorBlink 0.8s step-end infinite;
  margin-left: 1px;
}

@keyframes cursorBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.copy-btn {
  padding: 0.25rem 0.625rem;
  font-size: 0.6875rem;
  font-weight: 600;
  background: var(--grey-700);
  color: var(--grey-200);
  border: 1px solid var(--grey-600);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: var(--font-primary);
}

.copy-btn:hover {
  background: var(--grey-600);
  color: var(--white);
}

/* IDE Install Row */
.ide-install {
  display: inline-flex;
  align-items: center;
  gap: 0;
  border-radius: 10px;
  border: 1px solid var(--border-strong);
  overflow: hidden;
  margin-bottom: 0.75rem;
  animation: fadeInUp 0.4s ease-out 0.35s both;
}

.ide-install-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
  border-right: 1px solid var(--border);
  position: relative;
  font-family: var(--font-primary);
  white-space: nowrap;
  min-height: 2.5rem;
}

.ide-install-btn:last-child {
  border-right: none;
}

.ide-install-btn svg,
.ide-install-btn img {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
}

.ide-install-btn--primary {
  background: var(--grey-900);
  color: var(--white);
  cursor: pointer;
}

.ide-install-btn--primary:hover {
  background: var(--black);
  color: var(--white);
  text-decoration: none;
}

.ide-install-btn--primary img {
  filter: brightness(1.2);
}

.ide-install-btn--soon {
  background: var(--bg);
  color: var(--text-muted);
  cursor: default;
}

.ide-install-btn--soon svg,
.ide-install-btn--soon img {
  opacity: 0.5;
}

.ide-soon-tag {
  font-size: 0.5625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent);
  background: var(--accent-bg);
  padding: 0.1rem 0.35rem;
  border-radius: 3px;
  line-height: 1;
}

/* Why Section */
.why-section {
  margin-top: 2.5rem;
}

.why-subtext {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

.why-stats {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .why-stats { grid-template-columns: 1fr 1fr 1fr; }
}

.why-stat-card {
  display: flex;
  flex-direction: column;
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-subtle);
  text-align: center;
}

.why-stat-number {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.why-stat-unit {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.why-stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 0.375rem;
}

/* Section Divider & Header */
.section-divider {
  height: 1px;
  background: var(--border);
  margin-bottom: 1.5rem;
}

.section-header {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--accent);
  display: inline-block;
}

.section-cta {
  margin-top: 1.25rem;
}

.article section { 
  margin-top: 2.5rem; 
}

.article section h2 { 
  margin-bottom: 1rem; 
}

.article ul, .article ol {
  margin: 0.75rem 0;
  padding-left: 1.5rem;
  color: var(--text-secondary);
}

.article li { 
  margin: 0.5rem 0; 
  line-height: 1.7;
}

/* Author card */
.author-card {
  padding: 1.5rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-subtle);
}

.author-info h3 {
  margin: 0 0 0.75rem;
  font-size: 1.125rem;
}

.author-info p {
  margin: 0 0 1.25rem;
}

.github-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 500;
  padding: 0.5rem 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  transition: all 0.15s ease;
}

.github-link:hover {
  border-color: var(--text-primary);
  text-decoration: none;
}

/* Cat agent — minimal idle motion */
.cat-agent {
  display: inline-flex;
  align-items: center;
  color: var(--text-muted);
  opacity: 0.55;
  transition: opacity 0.4s ease;
}

.cat-agent:hover {
  opacity: 0.85;
}

.cat-eye {
  animation: cat-blink 4s ease-in-out infinite;
}

.cat-eye-right {
  animation-delay: 0.1s;
}

@keyframes cat-blink {
  0%, 90%, 100% { ry: 1.2; }
  94%, 96% { ry: 0.15; }
}

.cat-tail {
  transform-origin: 42px 27px;
  animation: cat-tail-sway 3s ease-in-out infinite;
}

@keyframes cat-tail-sway {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(8deg); }
}

/* About page */
.about-role {
  font-size: 0.8125rem;
  color: var(--accent);
  font-weight: 600;
  letter-spacing: 0.02em;
  margin-bottom: 0.75rem !important;
}

.about-links {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 1.25rem;
}

.about-highlights {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.about-highlight-card {
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-subtle);
  transition: border-color 0.2s ease;
}
.about-highlight-card:hover {
  border-color: var(--accent);
}

.about-highlight-icon {
  display: block;
  font-size: 1.25rem;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.about-highlight-card h4 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.35rem;
}

.about-highlight-card p {
  font-size: 0.8125rem;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0;
}

/* Wiki terms */
.wiki-terms {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 1rem;
}

.wiki-term {
  padding: 1rem 1.25rem;
  border-left: 3px solid var(--accent);
  background: var(--bg-subtle);
  border-radius: 0 8px 8px 0;
}

.wiki-term h4 {
  margin: 0 0 0.5rem;
  color: var(--text-primary);
}

.wiki-term p {
  margin: 0;
  font-size: 0.8125rem;
}

/* Feature grid */
.feature-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 1rem;
}

@media (min-width: 640px) {
  .feature-grid { grid-template-columns: 1fr 1fr; }
}

.feature-item {
  position: relative;
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: all 0.15s ease;
}

.feature-item:hover {
  border-color: var(--grey-400);
}

.feature-item--extension {
  background: var(--bg-subtle);
}

.feature-item--extension:hover {
  border-color: var(--accent);
  box-shadow: 0 2px 8px rgba(227, 18, 11, 0.06);
}

.feature-number {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6875rem;
  font-weight: 700;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: 50%;
}

.feature-badge {
  display: inline-block;
  font-size: 0.5625rem;
  font-weight: 600;
  padding: 0.15em 0.5em;
  border-radius: 4px;
  margin-top: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.feature-badge--extension {
  background: var(--accent-bg);
  color: var(--accent);
}

.feature-badge--mcp {
  background: rgba(99, 102, 241, 0.10);
  color: #6366f1;
}

.feature-badge--cli {
  background: rgba(20, 184, 166, 0.10);
  color: #14b8a6;
}

.feature-badge--web {
  background: var(--accent-bg);
  color: var(--accent);
}

.feature-badge--soon {
  background: rgba(168, 85, 247, 0.12);
  color: #a855f7;
}

.feature-item--coming-soon {
  border: 1px dashed rgba(168, 85, 247, 0.25);
  opacity: 0.92;
}

.feature-item h3 {
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
}

.feature-item p {
  font-size: 0.8125rem;
  line-height: 1.6;
}

.feature-item code {
  display: inline-block;
  margin-top: 0.5rem;
  font-size: 0.75rem;
}

/* Tool grid */
.tool-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  margin-top: 1rem;
}

@media (min-width: 640px) {
  .tool-grid { grid-template-columns: 1fr 1fr; }
}

.tool-card {
  display: block;
  position: relative;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: all 0.15s ease;
  text-decoration: none;
  border-left: 3px solid transparent;
}

.tool-card:hover {
  border-color: var(--grey-400);
  border-left-color: var(--accent);
  text-decoration: none;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.tool-card h3 {
  font-size: 0.875rem;
  color: var(--text-primary);
}

.tool-card p {
  font-size: 0.8125rem;
  margin-top: 0.25rem;
}

/* 3-column feature grid for extension page */
@media (min-width: 640px) {
  .feature-grid--3col { grid-template-columns: 1fr 1fr; }
}
@media (min-width: 900px) {
  .feature-grid--3col { grid-template-columns: 1fr 1fr 1fr; }
}

/* Architecture grid */
.arch-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  margin-top: 1rem;
}

@media (min-width: 640px) {
  .arch-grid { grid-template-columns: 1fr 1fr; }
}

.arch-card {
  position: relative;
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-subtle);
  transition: border-color 0.15s ease;
}

.arch-card:hover {
  border-color: var(--grey-400);
}

.arch-card h3 {
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
}

.arch-card p {
  font-size: 0.8125rem;
  line-height: 1.6;
}

/* Install methods */
.install-methods {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 1rem;
}

@media (min-width: 640px) {
  .install-methods { grid-template-columns: 1fr 1fr 1fr; }
}

.install-method-card {
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg);
  transition: border-color 0.15s ease;
}

.install-method-card:hover {
  border-color: var(--grey-400);
}

.install-method-card h3 {
  font-size: 0.875rem;
  margin-bottom: 0;
}

.install-method-card .install-cmd {
  width: 100%;
}

/* 4-column stats for extension page */
@media (min-width: 640px) {
  .why-stats--4col { grid-template-columns: 1fr 1fr 1fr 1fr; }
}

/* Install block */
.install-block {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  background: var(--grey-900);
  color: var(--grey-100);
  border-radius: 8px;
  padding: 1rem 1.25rem;
}

/* Keyboard styling */
kbd {
  display: inline-block;
  padding: 0.2rem 0.5rem;
  font-size: 0.75rem;
  font-family: var(--font-mono);
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: 4px;
  box-shadow: 0 2px 0 var(--grey-300);
}

/* Tables */
.settings-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
  margin-top: 1rem;
}

.settings-table th,
.settings-table td {
  text-align: left;
  padding: 0.75rem;
  border-bottom: 1px solid var(--border);
}

.settings-table th {
  font-weight: 600;
  color: var(--text-muted);
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Badge */
.badge {
  font-size: 0.625rem;
  font-weight: 600;
  padding: 0.2em 0.6em;
  border-radius: 4px;
  margin-left: 0.5rem;
}

.badge-accent {
  background: var(--accent-bg);
  color: var(--accent);
}

/* Wiki */
.wiki-search {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.wiki-search-input {
  flex: 1;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text-primary);
  font-family: var(--font-primary);
  transition: border-color 0.15s ease;
}

.wiki-search-input:focus {
  outline: none;
  border-color: var(--accent);
}

.wiki-search-input::placeholder {
  color: var(--text-muted);
}

.wiki-search-count {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.wiki-filters {
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.wiki-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.source-pill,
.category-pill {
  padding: 0.25rem 0.625rem;
  font-size: 0.6875rem;
  font-weight: 500;
  border: 1px solid var(--border);
  border-radius: 9999px;
  background: var(--bg);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: var(--font-primary);
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

.source-pill:hover,
.category-pill:hover {
  border-color: var(--grey-400);
  color: var(--text-primary);
}

.source-pill.active,
.category-pill.active {
  background: var(--text-primary);
  border-color: var(--text-primary);
  color: var(--bg);
}

.source-pill-count {
  font-size: 0.5625rem;
  opacity: 0.7;
}

.wiki-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .wiki-grid { grid-template-columns: 1fr 1fr; }
}

.wiki-card {
  display: block;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  text-decoration: none;
  transition: all 0.15s ease;
}

.wiki-card:hover {
  border-color: var(--grey-400);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  text-decoration: none;
}

.wiki-card-header {
  display: flex;
  gap: 0.375rem;
  align-items: center;
  margin-bottom: 0.5rem;
  flex-wrap: wrap;
}

.source-badge {
  display: inline-block;
  font-size: 0.5625rem;
  font-weight: 600;
  padding: 0.125em 0.5em;
  border-radius: 4px;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.category-badge {
  display: inline-block;
  font-size: 0.5625rem;
  font-weight: 500;
  padding: 0.125em 0.5em;
  border-radius: 4px;
  background: var(--bg-muted);
  color: var(--text-muted);
  text-transform: capitalize;
}

.wiki-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
  line-height: 1.3;
}

.wiki-card:hover .wiki-card-title {
  color: var(--accent);
}

.wiki-card-desc {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0;
}

.wiki-card-meta {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.5rem;
  font-size: 0.6875rem;
  color: var(--text-muted);
}

.wiki-card-tags {
  display: flex;
  gap: 0.25rem;
  flex-wrap: wrap;
  margin-top: 0.5rem;
}

.wiki-tag {
  font-size: 0.5625rem;
  padding: 0.1em 0.4em;
  border-radius: 3px;
  background: var(--bg-muted);
  color: var(--text-muted);
}

.wiki-tag--more {
  color: var(--text-secondary);
}

.wiki-empty {
  text-align: center;
  padding: 3rem 0;
}

.wiki-empty p {
  margin-bottom: 1rem;
}

/* Wiki Breadcrumb */
.wiki-breadcrumb {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.wiki-breadcrumb a {
  color: var(--accent);
}

.wiki-breadcrumb-sep {
  margin: 0 0.375rem;
  color: var(--grey-300);
}

/* Wiki Content (rendered markdown) */
.wiki-content h1 { font-size: 1.25rem; margin: 1.5rem 0 0.75rem; }
.wiki-content h2 { font-size: 1.0625rem; margin: 1.25rem 0 0.625rem; padding-bottom: 0.375rem; border-bottom: 1px solid var(--border); }
.wiki-content h3 { font-size: 0.9375rem; margin: 1rem 0 0.5rem; }
.wiki-content h4 { font-size: 0.875rem; margin: 0.75rem 0 0.375rem; }
.wiki-content p { margin-bottom: 0.75rem; font-size: 0.8125rem; line-height: 1.7; }
.wiki-content ul, .wiki-content ol { margin: 0.5rem 0; padding-left: 1.5rem; color: var(--text-secondary); font-size: 0.8125rem; }
.wiki-content li { margin: 0.25rem 0; line-height: 1.6; }
.wiki-content a { color: var(--accent); text-decoration: underline; }
.wiki-content blockquote { border-left: 3px solid var(--accent); padding-left: 1rem; color: var(--text-muted); margin: 0.75rem 0; font-style: italic; }
.wiki-content hr { border: none; border-top: 1px solid var(--border); margin: 1.5rem 0; }

/* How-to-use steps — Agentation-inspired */
.how-to-steps {
  list-style: none;
  padding: 0;
  margin: 1.25rem 0 0;
  counter-reset: none;
}

.how-to-step {
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  animation: fadeInUp 0.4s ease-out both;
}

.how-to-step:last-child {
  border-bottom: none;
}

.how-to-num {
  flex-shrink: 0;
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6875rem;
  font-weight: 700;
  background: var(--bg-muted);
  color: var(--text-primary);
  border-radius: 50%;
  margin-top: 0.1rem;
}

.how-to-step:hover .how-to-num {
  background: var(--accent);
  color: var(--white);
}

/* ── Technical Details (Quick Start) ───────── */
.tech-details {
  margin-top: 2rem;
  padding: 1.25rem 1.5rem;
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
}
.tech-details-title {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  margin: 0 0 1rem;
}
.tech-details-list {
  display: grid;
  gap: 0.75rem;
  margin: 0;
}
.tech-details-item {
  display: grid;
  grid-template-columns: 7rem 1fr;
  gap: 0.75rem;
  font-size: 0.8125rem;
  line-height: 1.5;
}
.tech-details-item dt {
  font-weight: 600;
  color: var(--text-primary);
}
.tech-details-item dd {
  margin: 0;
  color: var(--text-secondary);
}

/* ── Command Grid ──────────────────────────── */
.command-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 0.75rem;
  margin-top: 1.25rem;
}
.command-card {
  padding: 1rem 1.25rem;
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: 0.625rem;
  transition: border-color 0.2s;
}
.command-card:hover {
  border-color: var(--accent);
}
.command-name {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent);
  background: none;
  padding: 0;
  margin: 0 0 0.375rem;
  font-family: var(--font-mono, monospace);
}
.command-desc {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
  margin: 0;
}

/* ── Star Button ───────────────────────────── */
.cta-star {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.625rem 1.25rem;
  background: transparent;
  color: #f5a623;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: 8px;
  text-decoration: none;
  border: 1px solid rgba(245, 166, 35, 0.35);
  transition: all 0.2s ease;
}
.cta-star:hover {
  background: rgba(245, 166, 35, 0.1);
  border-color: #f5a623;
  color: #f5a623;
  text-decoration: none;
  transform: translateY(-1px);
}
.cta-star svg {
  transition: transform 0.3s ease;
}
.cta-star:hover svg {
  transform: scale(1.2) rotate(15deg);
}

.cta-star--large {
  padding: 0.75rem 2rem;
  font-size: 1rem;
  border-width: 1.5px;
}

/* ── Community Section ────────────────────── */
.community-section {
  position: relative;
  margin-top: 3rem;
  padding: 3rem 0;
  text-align: center;
  overflow: hidden;
}

.community-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 400px;
  height: 400px;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(227, 18, 11, 0.06) 0%, transparent 70%);
  pointer-events: none;
  animation: glowPulse 4s ease-in-out infinite;
}

@keyframes glowPulse {
  0%, 100% { opacity: 0.4; transform: translate(-50%, -50%) scale(1); }
  50% { opacity: 0.8; transform: translate(-50%, -50%) scale(1.1); }
}

.community-content {
  position: relative;
  z-index: 1;
  max-width: 520px;
  margin: 0 auto;
}

.community-emoji {
  font-size: 2.5rem;
  display: block;
  margin-bottom: 1rem;
  animation: float 3s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.community-headline {
  font-size: 1.375rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 0.75rem;
  color: var(--text-primary);
}

.community-text {
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

.community-ctas {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}

.community-values {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.community-value {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.75rem;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

.community-value-icon {
  color: var(--accent);
  font-size: 0.85rem;
}

.community-value-icon--pulse {
  display: inline-block;
  transform-origin: center;
  animation: communityPulse 2.2s ease-in-out infinite;
}

.community-value-icon--orbit {
  display: inline-block;
  transform-origin: center;
  animation: communityOrbit 3.5s ease-in-out infinite;
}

@keyframes communityPulse {
  0%, 100% { transform: scale(1); opacity: 0.9; }
  45% { transform: scale(1.15); opacity: 1; }
}

@keyframes communityOrbit {
  0% { transform: rotate(0deg) translateY(0); opacity: 0.9; }
  50% { transform: rotate(8deg) translateY(-1px); opacity: 1; }
  100% { transform: rotate(0deg) translateY(0); opacity: 0.9; }
}

@media (prefers-reduced-motion: reduce) {
  .community-value-icon--pulse,
  .community-value-icon--orbit {
    animation: none;
  }
}

/* Istanbul Cat — minimal face */
.istanbul-cat-wrap {
  display: inline-flex;
  align-items: center;
  color: var(--text-muted);
  opacity: 0.55;
  transition: opacity 0.3s ease;
  cursor: default;
}

.istanbul-cat-wrap:hover {
  opacity: 0.9;
}

/* Istanbul value pill */
.community-value--istanbul {
  gap: 0.3rem !important;
}

/* Footer */
.footer {
  margin-top: 4rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.footer-nav {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  padding-bottom: 2rem;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--border);
}

.footer-nav-col {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-nav-heading {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-primary);
  margin: 0 0 0.25rem 0;
}

.footer-nav-col a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.15s ease;
}

.footer-nav-col a:hover {
  color: var(--text-primary);
}

.footer-main {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  flex-wrap: wrap;
}

.footer-brand {
  font-weight: 600;
  color: var(--text-secondary);
}

.footer-author-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
}
.footer-author-link:hover {
  color: var(--text-primary);
}

.footer-love {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.footer-love-icon {
  display: inline-block;
  font-size: 1.25em;
  color: var(--text-primary);
  cursor: default;
  transition: transform 0.3s ease, color 0.3s ease;
}

.footer-love-icon.heart-active {
  animation: heartBeat 1.2s ease-in-out infinite, heartColors 3s ease-in-out infinite;
}

/* Shared heart animations — realistic double-pulse + color cycling */
@keyframes heartBeat {
  0%   { transform: scale(1); }
  14%  { transform: scale(1.25); }
  28%  { transform: scale(1); }
  42%  { transform: scale(1.2); }
  56%  { transform: scale(1); }
  100% { transform: scale(1); }
}

@keyframes heartColors {
  0%   { color: var(--accent); }
  25%  { color: #d4a017; }
  50%  { color: #e3120b; }
  75%  { color: #cc3366; }
  100% { color: var(--accent); }
}

.footer-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.75rem;
}

.footer-github {
  display: flex;
  align-items: center;
  color: var(--text-muted);
  transition: color 0.15s ease;
}
.footer-github:hover {
  color: var(--text-primary);
}

.footer-clock {
  font-size: 0.6875rem;
  font-family: var(--font-mono);
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

.footer a { color: var(--text-secondary); }
.footer a:hover { color: var(--text-primary); }

/* ── Learn Page ───────────────────────────── */
.learn-frame {
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid var(--grey-200);
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  margin: 1.5rem 0;
}

.learn-frame-dark {
  border: 1px solid #333;
  box-shadow: 0 2px 16px rgba(0,0,0,0.3);
}

.learn-frame-body {
  background: var(--white);
}

.learn-code-dark {
  border: 1px solid #333;
  background: #0a0a0a;
}

.learn-compare-dark {
  border: 1px solid #333;
}
.learn-compare-dark table {
  background: #111;
}
.learn-compare-dark tr:hover td {
  background: rgba(227,18,11,0.05);
}

.learn-frame-pad {
  padding: 16px 20px;
}

.learn-turns-row {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.learn-side-by-side {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* Lessons */
.learn-lesson {
  margin-bottom: 3rem;
  padding-top: 1rem;
  scroll-margin-top: 2rem;
}

.learn-lesson-header {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.learn-lesson-num {
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: var(--accent);
  color: white;
  font-size: 0.875rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 0.125rem;
}

.learn-lesson-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}

.learn-lesson-sub {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin: 0.125rem 0 0;
}

.learn-lesson-desc {
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

/* Context window visual */
.learn-window-visual {
  padding: 16px 20px;
}

.learn-window-segments {
  display: flex;
  border-radius: 6px;
  overflow: hidden;
  height: 48px;
}

.learn-segment {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 0;
  transition: flex 0.3s ease;
}

.learn-segment-label {
  font-size: 0.5625rem;
  font-weight: 600;
  color: white;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 90%;
  text-align: center;
}

.learn-segment-pct {
  font-size: 0.625rem;
  font-weight: 700;
  color: rgba(255,255,255,0.8);
}

.learn-window-meta {
  display: flex;
  gap: 1.5rem;
  margin-top: 0.75rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Code blocks */
.learn-code {
  border-radius: 8px;
  border: 1px solid var(--grey-200);
  overflow: hidden;
  margin: 1rem 0;
  background: var(--grey-50);
}

.learn-code-header {
  padding: 0.375rem 0.75rem;
  border-bottom: 1px solid var(--grey-200);
  background: var(--white);
}

.learn-code-lang {
  font-size: 0.625rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.learn-code-pre {
  margin: 0;
  padding: 0.75rem 0;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  line-height: 1.7;
  overflow-x: auto;
}

.learn-code-line {
  display: flex;
  gap: 0.75rem;
  padding: 0 0.75rem;
}

.learn-code-num {
  color: var(--grey-300);
  width: 1.25rem;
  text-align: right;
  flex-shrink: 0;
  user-select: none;
}

/* Progress bars */
.learn-progress {
  margin-bottom: 0.625rem;
}

.learn-progress-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.6875rem;
  color: var(--text-secondary);
  margin-bottom: 0.25rem;
}

.learn-progress-track {
  height: 6px;
  border-radius: 3px;
  background: var(--grey-100);
  overflow: hidden;
}

.learn-progress-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.6s ease-out;
}

/* Badges */
.learn-badge {
  display: inline-block;
  font-size: 0.5625rem;
  font-weight: 600;
  padding: 0.15em 0.5em;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.learn-budget-summary {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
}

/* Compaction visual */
.learn-compact-visual {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 1.5rem;
  padding: 20px;
}

.learn-compact-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.375rem;
  flex: 1;
  max-width: 120px;
}

.learn-compact-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.learn-compact-bar {
  width: 100%;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: height 0.6s ease;
}

.learn-compact-val {
  font-size: 0.625rem;
  font-weight: 700;
  color: var(--text-primary);
}

.learn-compact-detail {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-align: center;
}

.learn-compact-arrow {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.learn-compact-strategies {
  padding: 0 20px 16px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.375rem;
}

.learn-compact-strategy {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.6875rem;
  color: var(--text-secondary);
}

.learn-compact-check {
  color: var(--accent);
  font-weight: 700;
  font-size: 0.75rem;
}

/* Course nav */
.learn-nav {
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--grey-200);
  border-radius: 10px;
  background: var(--grey-50);
}

.learn-nav h3 {
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.learn-nav-items {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.learn-nav-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text-primary);
  transition: background 0.15s ease;
}

.learn-nav-item:hover {
  background: var(--white);
  text-decoration: none;
}

.learn-nav-num {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background: var(--accent-bg);
  color: var(--accent);
  font-size: 0.6875rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.learn-nav-item strong {
  font-size: 0.8125rem;
  display: block;
}

.learn-nav-sub {
  font-size: 0.6875rem;
  color: var(--text-muted);
  display: block;
}

/* Learn — Comparison table */
.learn-compare-table {
  margin: 20px 0;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--grey-200);
}
.learn-compare-table table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}
.learn-compare-table th {
  padding: 10px 14px;
  text-align: left;
  background: var(--grey-050);
  border-bottom: 1px solid var(--grey-200);
  font-weight: 600;
  font-size: 0.75rem;
  letter-spacing: 0.02em;
}
.learn-compare-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--grey-100);
  line-height: 1.4;
}
.learn-compare-table tr:last-child td { border-bottom: none; }
.learn-compare-table tr:hover td { background: var(--grey-050); }

/* Scrollbar */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--grey-300); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--grey-400); }

/* Dictionary */
.dict-letter-index {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border);
}

.dict-letter-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  border-radius: 6px;
  text-decoration: none;
  transition: all 0.15s ease;
}

.dict-letter-link:hover {
  color: var(--accent);
  border-color: var(--accent);
  background: var(--accent-bg);
  text-decoration: none;
}

.dict-letter-header {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
  padding: 0.5rem 0 0.25rem;
  margin-top: 1.5rem;
  border-bottom: 2px solid var(--accent);
  display: inline-block;
  margin-bottom: 0.75rem;
}

.dict-terms {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dict-term {
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: border-color 0.15s ease;
  animation: fadeIn 0.3s ease-out both;
}

.dict-term:hover {
  border-color: var(--grey-400);
}

.dict-term-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
  flex-wrap: wrap;
}

.dict-term-name {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}

.dict-term-def {
  font-size: 0.8125rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 0.5rem;
}

/* iPhone responsive */
@media (max-width: 430px) {
  body {
    font-size: 0.8125rem;
  }

  h1 { font-size: 1.125rem; }
  h2 { font-size: 0.9375rem; }

  .hero-headline {
    font-size: 1.5rem;
  }

  .hero-icon {
    font-size: 2rem;
  }

  .hero-outline-icon svg {
    width: 36px;
    height: 36px;
  }

  .hero-ctas {
    flex-direction: column;
  }

  .hero-ctas .cta-primary,
  .hero-ctas .cta-secondary {
    width: 100%;
    text-align: center;
  }

  .coming-soon-badge {
    width: 100%;
    justify-content: center;
  }

  .install-cmd {
    width: 100%;
    justify-content: space-between;
  }

  .ide-install {
    flex-direction: column;
    width: 100%;
    border-radius: 10px;
  }

  .ide-install-btn {
    width: 100%;
    justify-content: center;
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 0.75rem 1rem;
  }

  .ide-install-btn:last-child {
    border-bottom: none;
  }

  .why-stats {
    grid-template-columns: 1fr;
  }

  .main-content {
    padding: 0.875rem;
  }

  .article {
    max-width: 100%;
  }

  .article header {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
  }

  .article section {
    margin-top: 1.75rem;
  }

  .feature-grid,
  .tool-grid {
    grid-template-columns: 1fr;
  }

  .feature-item,
  .tool-card {
    padding: 1rem;
  }

  .author-card {
    padding: 1rem;
  }

  .about-highlights {
    grid-template-columns: 1fr;
  }

  pre {
    padding: 0.75rem 1rem;
    font-size: 0.75rem;
  }

  .section-header {
    font-size: 1rem;
  }

  .section-divider {
    margin-bottom: 1rem;
  }

  .hero {
    margin-bottom: 1.75rem;
    padding-bottom: 1.5rem;
  }

  .hero-description {
    font-size: 0.875rem;
  }

  .why-stat-card {
    padding: 1rem;
  }

  .why-stat-number {
    font-size: 1.125rem;
  }

  /* Tables horizontal scroll on small screens */
  .settings-table {
    display: block;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    font-size: 0.75rem;
  }

  .settings-table th,
  .settings-table td {
    padding: 0.5rem 0.625rem;
    white-space: nowrap;
  }

  /* Chart containers */
  .eco-card-flat {
    padding: 0.75rem;
    overflow-x: auto;
  }

  /* Nav link sizing */
  .nav-link {
    padding: 0.5rem 1rem;
    font-size: 0.8125rem;
  }

  .nav-section-label {
    padding: 0.625rem 1rem 0.375rem;
  }

  /* Dictionary on small screens */
  .dict-letter-link {
    width: 1.75rem;
    height: 1.75rem;
    font-size: 0.6875rem;
  }

  .dict-term {
    padding: 0.75rem 1rem;
  }

  /* How-to steps */
  .how-to-step {
    gap: 0.625rem;
    font-size: 0.8125rem;
  }

  .how-to-num {
    width: 1.25rem;
    height: 1.25rem;
    font-size: 0.625rem;
  }

  /* Footer */
  .footer {
    margin-top: 2.5rem;
    padding-top: 1.25rem;
  }

  .footer-nav {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem 1rem;
  }

  /* Wiki */
  .wiki-term {
    padding: 0.75rem 1rem;
  }

  .wiki-filters {
    margin-bottom: 1rem;
  }

  .wiki-filter-row {
    gap: 0.25rem;
  }

  .source-pill,
  .category-pill {
    font-size: 0.625rem;
    padding: 0.2rem 0.5rem;
  }

  /* Demo mockup small phones */
  .demo-mockup-wrapper { margin: 1.5rem auto 0; }
  .demo-body { flex-direction: column; min-height: auto; }
  .demo-sidebar { width: 100%; border-right: none; border-bottom: 1px solid var(--grey-200); padding: 8px; }
  .demo-chat-panel { width: 100%; border-left: none; border-top: 1px solid var(--grey-200); }
  .demo-code { font-size: 7.5px; line-height: 1.6; }
  .demo-code-line { gap: 6px; padding: 0 6px; }
  .demo-legend { gap: 0.75rem; }
  .demo-legend-item { font-size: 10px; }

  /* ── Learn page small phones ── */
  .learn-lesson-num {
    width: 1.5rem;
    height: 1.5rem;
    font-size: 0.6875rem;
  }

  .learn-lesson-title {
    font-size: 0.9375rem;
  }

  .learn-lesson-sub {
    font-size: 0.6875rem;
  }

  .learn-lesson-desc {
    font-size: 0.75rem;
    line-height: 1.6;
  }

  .learn-window-segments {
    height: 36px;
  }

  .learn-segment-label {
    font-size: 0.375rem;
  }

  .learn-code-pre {
    font-size: 0.5625rem;
  }

  .learn-compact-visual {
    gap: 0.5rem;
    padding: 10px;
  }

  .learn-compact-col {
    max-width: 80px;
  }

  .learn-compact-bar {
    border-radius: 4px;
  }

  .learn-compact-val {
    font-size: 0.4375rem;
  }

  .learn-compact-detail {
    font-size: 0.5625rem;
  }

  .learn-compact-label {
    font-size: 0.5625rem;
  }

  .learn-compact-arrow svg {
    width: 24px;
    height: 24px;
  }
}

/* Extra small phones (iPhone SE, Galaxy S, etc.) */
@media (max-width: 360px) {
  body {
    font-size: 0.75rem;
  }

  h1 { font-size: 1rem; }
  h2 { font-size: 0.875rem; }

  .hero-headline {
    font-size: 1.25rem;
