    30→// ── Cost engine ────────────────────────────────────────────────────────────────
    31→type M = typeof PROVIDER_MODELS[number];
    32→const calcCost = (m: M, inp: number, out: number, cw = 0, cr = 0) => {
    33→  const ic  = (inp / 1_000_000) * m.inputCostPerMTok;
