"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState, useEffect, useRef, useCallback } from "react";
import siteContent from "../content/site.json";

type NavItem = { href: string; label: string; badge?: string };
type NavSection = { section: string; items: NavItem[]; collapsible?: boolean };

const nav: NavSection[] = siteContent.nav as NavSection[];

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <svg
      width="10"
      height="10"
      viewBox="0 0 10 10"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{
        transition: "transform 0.2s ease",
        transform: open ? "rotate(90deg)" : "rotate(0deg)",
      }}
    >
      <polyline points="3,2 7,5 3,8" />
    </svg>
  );
}

function GitHubIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 16 16" fill="currentColor">
      <path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0016 8c0-4.42-3.58-8-8-8z" />
    </svg>
  );
}

function SidebarHeart() {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => setActive(entry.isIntersecting),
      { threshold: 0.5 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  return (
    <div className="sidebar-made-by" ref={ref}>
      Made by{" "}
      <a href={siteContent.authorGithub} target="_blank" rel="noopener noreferrer">
        Vahid Faraji
      </a>
      {" "}with <span className={`sidebar-heart${active ? " heart-active" : ""}`}>&hearts;</span> from Istanbul
    </div>
  );
}

export function SideNav() {
  const pathname = usePathname();

  // Track which collapsible sections are open
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});

  // Mobile menu open state
  const [menuOpen, setMenuOpen] = useState(false);

  // Auto-expand sections containing the active route
  useEffect(() => {
    const expanded: Record<string, boolean> = {};
    nav.forEach((section) => {
      if (section.collapsible) {
        const hasActive = section.items.some(
          (item) =>
            pathname === item.href ||
            (item.href !== "/" && pathname.startsWith(item.href))
        );
        if (hasActive) expanded[section.section] = true;
      }
    });
    setCollapsed((prev) => ({ ...prev, ...expanded }));
  }, [pathname]);

  // Close mobile menu on route change
  const closeMobileMenu = useCallback(() => setMenuOpen(false), []);
  useEffect(() => {
    closeMobileMenu();
  }, [pathname, closeMobileMenu]);

  const toggleSection = (section: string) => {
    setCollapsed((prev) => ({ ...prev, [section]: !prev[section] }));
  };

  return (
    <>
      {/* Mobile header — icon logo + hamburger */}
      <div className="mobile-header">
        <Link href="/" className="mobile-logo">
          <span className="mobile-logo-at">@</span>
          <span className="mobile-logo-text">Tokalator</span>
        </Link>
        <button
          className="mobile-menu-btn"
          onClick={() => setMenuOpen((v) => !v)}
          aria-label={menuOpen ? "Close menu" : "Open menu"}
          type="button"
        >
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
            {menuOpen ? (
              <>
                <line x1="4" y1="4" x2="16" y2="16" />
                <line x1="16" y1="4" x2="4" y2="16" />
              </>
            ) : (
              <>
                <line x1="3" y1="5" x2="17" y2="5" />
                <line x1="3" y1="10" x2="17" y2="10" />
                <line x1="3" y1="15" x2="17" y2="15" />
              </>
            )}
          </svg>
        </button>
      </div>

      {/* Mobile overlay */}
      {menuOpen && (
        <div className="mobile-overlay" onClick={() => setMenuOpen(false)} />
      )}

      {/* Mobile slide-down menu */}
      <div className={`mobile-menu ${menuOpen ? "mobile-menu--open" : ""}`}>
        {nav.map((section) => (
          <div key={section.section} className="mobile-menu-section">
            <div className="mobile-menu-section-label">{section.section}</div>
            {section.items.map((item) => {
              const isActive =
                pathname === item.href ||
                (item.href !== "/" && pathname.startsWith(item.href));
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`mobile-menu-link ${isActive ? "mobile-menu-link--active" : ""}`}
                  onClick={() => setMenuOpen(false)}
                >
                  {item.label}
                  {item.badge && <span className="nav-badge">{item.badge}</span>}
                </Link>
              );
            })}
          </div>
        ))}
        <div className="mobile-menu-footer">
          <a
            href={siteContent.authorGithub}
            target="_blank"
            rel="noopener noreferrer"
            className="sidebar-github-link"
            aria-label="GitHub Profile"
          >
            <GitHubIcon />
          </a>
          <span className="mobile-menu-version">{siteContent.version}</span>
        </div>
      </div>

      {/* Sidebar */}
      <nav className="sidebar">
        <div className="sidebar-header">
          <Link href="/" className="sidebar-logo">
            <span className="sidebar-at">@</span>
