/* ── Events & Talks ── */

.events-list {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  margin-top: 1.5rem;
}

.event-card {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.75rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.event-card:hover {
  border-color: var(--grey-400);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
}

.event-card-image {
  margin-bottom: 1.25rem;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.event-card-header {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 0.75rem;
}

.event-status-badge {
  display: inline-block;
  font-size: 0.625rem;
  font-weight: 700;
  padding: 0.2em 0.6em;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.event-status--upcoming {
  background: #e3120b;
  color: #fff;
}

.event-status--past {
  background: var(--bg-muted);
  color: var(--text-muted);
}

.event-series-badge {
  font-size: 0.625rem;
  color: var(--text-muted);
  font-weight: 500;
  padding: 0.15em 0.5em;
  border-radius: 4px;
  background: var(--bg-muted);
}

.event-card-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 0.25rem;
  line-height: 1.3;
}

.event-card-speaker {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin: 0 0 0.75rem;
}

.event-card-meta {
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.event-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.event-card-desc {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin: 0 0 1.25rem;
}

.event-card-section {
  margin-bottom: 1rem;
}

.event-card-section h3 {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.event-topics-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.event-topics-list li {
  position: relative;
  padding-left: 1.1rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

.event-topics-list li::before {
  content: "◈";
  position: absolute;
  left: 0;
  color: #e3120b;
  font-size: 0.625rem;
  top: 0.35em;
}

.event-card-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: 1.25rem;
}

.event-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 0.8125rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
  background: #e3120b;
  color: #fff;
  border: 1px solid #e3120b;
}

.event-action-btn:hover {
  background: #c20f09;
  border-color: #c20f09;
  text-decoration: none;
}

.event-action-btn--secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.event-action-btn--secondary:hover {
  background: var(--bg-muted);
  border-color: var(--grey-400);
  color: var(--text-primary);
}

/* Event Banner (styled to match "AI-Native Software Dev / Only Builders Club") */
.event-banner {
  margin-bottom: 1.5rem;
  border-radius: 12px;
  overflow: hidden;
  background: linear-gradient(135deg, #1a3af5 0%, #0a1fcc 50%, #2248ff 100%);
