  letter-spacing: -0.02em;
  line-height: 1;
  text-transform: uppercase;
}

.event-banner-badge {
  display: inline-block;
  margin-top: 1rem;
  padding: 0.4em 1em;
  background: #fff;
  color: #1a3af5;
  font-size: 0.75rem;
  font-weight: 800;
  border-radius: 6px;
